(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lb"] = {"ui":{"skip":"Zum Inhalt sprangen","back":"← Zréck bei AI-gile","lang.button":"Sprooch: {name}","lang.dialog":"Wiel eng Sprooch","lang.search":"Sproochen sichen","lang.none":"Keng Sprooch passt","lang.notYet":"{name} ass nach net iwwersat","theme.aria":"Design wiesselen: hell, donkel oder schwaarz","theme.toLight":"Op hellt Design wiesselen","theme.toDark":"Op donkelt Design wiesselen","theme.toBlack":"Op schwaarzt Design wiesselen (richteg schwaarz, schounend fir OLED-Schiirmer)","words.underline":"Dës Wierder op der Säit ënnersträichen","words.underlineHelp":"Gëff mat der Maus iwwer e gepunktent Wuert oder tipp drop, fir ze gesinn, wat et heescht.","words.col.todo":"Kaarten, déi fir elo ausgewielt sinn: d'Team fänkt als nächst domat un.","words.col.doing":"Eng KI schafft grad un dëser Kaart.","words.col.review":"Eng KI ass fäerdeg mam Wierk; eng aner kontrolléiert et, ier et bei dech kënnt.","words.col.verify":"Waart op dech: probéier et aus a sot, ob et fonktionéiert.","words.col.team":"Deng Notizen oder Äntwerten, déi doropper waarden, vum Team opgeholl ze ginn.","words.col.done":"Fäerdeg an ugeholl.","index.title":"AI-gile: däin KI-Entwécklerteam, op enger Tafel","index.description":"AI-gile ass eng Kanban-Tafel fir KI-Programméierteams. Si schaffen, während s du schléifs; fir dech bleift ee kuerze Stapel: wat ze decidéieren, ze testen an unzehuelen ass.","hero.logoAlt":"AI-gile-Tafelsymbol","hero.h1.html":"Däin KI-Entwécklerteam, op enger&nbsp;Tafel.","hero.alpha":"🐣 Zouene Pre-Alpha","hero.alphaTitle":"Fréi an onfäerdeg: merci, dass du et ausprobéiers!","hero.lede":"Si bauen, während s du schléifs. Du wuess op a fënns ee kuerze Stapel: e puer Froen, e puer Saachen zum Testen, een oder zwee violett Diamanten. Klicken, unhuelen, zeréck bei däi Kaffi.","dl.windows":"Windows-App","dl.browser":"Am Browser lafen","dl.messenger":"📱 Messenger fir däin Handy","dl.soon":"Geschwënn","dl.notify":"🔔 Sot mer Bescheed, wann et opgeet","dl.notifySmall":"Alpha oder Beta","hero.secondary":"Agile, awer d'Team brauch ni e Stand-up-Kaffi. (Si maache Stand-ups trotzdem.)","pitch.h2":"AI-gile a sou villen Wierder, wéi s du wëlls","pitch.lede":"Wiel eng Längt, vun engem Wuert bis 144. All Längt ass eng eege Beschreiwung, geschriwwe fir déi Gréisst. Zéi de Schieber oder benotz d'Pfeiltaste.","pitch.rangeLabel":"Längt a Wierder","pitch.dice":"🎲 eng aner Versioun","pitch.words.one":"{n} Wuert","pitch.words.other":"{n} Wierder","pitch.letters.one":"{n} Buschtaf","pitch.letters.other":"{n} Buschtawen","pitch.chars.one":"{n} Zeechen","pitch.chars.other":"{n} Zeechen","count.line.html.one":"{n} Kaart elo op der Tafel","count.line.html.other":"{n} Kaarten elo op der Tafel","people.humans.html.one":"👥 {n} Mënsch","people.humans.html.other":"👥 {n} Mënschen","people.agents.html.one":"🤖 {n} Agent","people.agents.html.other":"🤖 {n} Agenten","people.working.html.one":"⚡ {n} grad op der Aarbecht","people.working.html.other":"⚡ {n} grad op der Aarbecht","pre.title":"AI-gile: hei entsteet eppes","pre.description":"Hei entsteet eppes. Eng Tafel, op där KI-Teams bauen, wat s du dir wënschs, an dir ënnerwee eppes bäibréngen. Fir de Moment eng zou Pre-Alpha mat Frënn.","pre.h1":"Hei entsteet eppes. 🤫","pre.line":"Eng Tafel, op där KI-Teams bauen, wat s du dir wënschs, an dir ënnerwee eppes bäibréngen. Fir de Moment eng zou Pre-Alpha mat Frënn.","pre.btn":"🔔 Sot mer Bescheed, wann et opgeet","pre.peek":"Hannert dem Glas: déi richteg Tafel, live. All Kaart ass e faarwege Balken.","pre.peekFake":"Hannert dem Glas: esou gesäit eng Tafel bei der Aarbecht aus.","pre.night":"🌙 Den Nuetswiechter ass um Poste · 😴 de Mënsch raschtet","features.aria":"Wat et mécht","f.pile.h":"Ee Stapel fir dech","f.pile.html":"<b>Fir dech</b> hält alles, wat op dech waart, vun alle Projeten: Froen, Saachen zum Testen, Aufgaben, déi nëmmen e Mënsch ka maachen. Deng Schlaang seet, wat als Nächst kënnt a wéi laang et dauert.","f.sleep.h":"Teams, déi schaffen, während s du schléifs","f.sleep.p":"All Projet huet e Lead an e Team vun KI-Agenten. Kommentéier eng Kaart, an d'Team erwächt, mécht d'Aarbecht an hëlt se zeréck mat Schrëtt, déi och e midde Mënsch verfollege kann.","f.tester.h":"Fir d'éischt kontrolléiert en KI-Tester","f.tester.p":"Ier eppes bei dech kënnt, geet en Tester d'Schrëtt an enger Kopie vun der App duerch a weist, wat en gesinn huet, mat engem Screenshot. Bliedert duerch déi, déi bestanen hunn, an huel se mat engem Klick un.","f.proof.h":"Beweiser, net Verspriechen","f.proof.p":"All Iwwergab weist, wat geännert gouf: d'Dateien, den Ënnerscheed, d'Screenshoten. Keng Apps méi opmaachen, fir ze kucken, ob et fäerdeg ass.","f.chat.h":"Schwätz mat dengen Leads","f.chat.p":"Eng Leescht wéi bei Discord: een Ikon pro Projet, violett Diamanten fir dat, wat dech brauch. Schreif engem Lead eng Iddi; en mécht Kaarten an e Plang dorausser, mat engem ✅ Go-Knäppchen.","f.tidy.h":"Hält sech selwer opgeraumt","f.tidy.p":"Verwandte Kaarten ginn zu enger zesummegeluecht, duerchenee Titele gi gefléckt, an e Token-Check hält de Code schlank. Manner, wat een wiesselt, manner, un dat een denke muss.","f.private.h":"Deng, op dengem Computer","f.private.li1":"D'Tafel leeft op dengem eegene Computer an äntwert nëmmen dir.","f.private.li2":"Privat Noriichten tëscht Leit sinn Enn-zu-Enn verschlësselt.","f.private.li3":"Keng Konten, keng Tracker, keng Cookien.","f.lang.h":"A denger Sprooch","f.lang.p":"Iwwer 120 Sproochen, vum Hollännesche, Walisesche a Japanesche bis zu Piroten, Yoda a Klingonesch, mat engem séieren Zeréckwiessel op Englesch fir d'Fachbegrëffer.","f.service.h":"Vun enger Iddi zu engem richtege Service","f.service.p":"Hues du mat KI eppes gebaut, wat d'Leit elo notzen? Markéier et als Service, an d'Tafel hëlleft dir, et gutt ze bedreiwen: Verfügbarkeetskontrollen, eng ëffentlech Statussäit, Zwëschefäll mat engem Réckbléck, Ännerungen, déi e Go brauchen, Sécherungen, déi all Dag kontrolléiert ginn. D'Hëllef léiert dir all Schrëtt ënnerwee.","msgr.h2":"AI-gile Messenger: däin Team an der Täsch","msgr.p1":"Schwätz mat dengem KI-Team, ouni de Board opzemaachen. Chat mat de Leads vun denge Projeten an denge Frënn, kuck d'Testschrëtt vun enger Kaart a beäntwert se, alles vun dengem Handy aus.","msgr.p2":"Fir et ze verbannen, scann en QR-Code op dengem Board. Déi éischte Kéier? E frëndleche Demo-Chat weist der alles.","msgr.when":"Fir d'éischt Android, duerno eng Web-Versioun fir Handyen an iPhone.","msgr.who":"De Lead vun dengem Projet","msgr.b1":"De Fix fir den Däischter-Modus ass fäerdeg. Wëlls de d'Testschrëtt?","msgr.b2":"Jo, gär!","msgr.b3":"1. Maach d'Astellungen op. 2. Wiel Däischter. Gesäit et richteg aus?","tl.aria":"Zäitleescht vum éischte Gespréich bis zur Roadmap","tl.h2":"Vum éischte Chat bis zu deem, wat kënnt","tl.lede":"Richteg Datumer an Auerzäiten, an denger eegener Zäitzon. Nom Haut ass et de Plang, ouni versprachent Datumer.","tl.today":"Haut","tl.planned":"geplangt","tl.doing":"amgaang","tl.cards.one":"{n} Kaart","tl.cards.other":"{n} Kaarten","join.h2":"Maach mat","join.lede":"AI-gile gëtt vun engem Original mat Baart, AuDHD an e puer Kämpf mat der mentaler Gesondheet a vu ganz villen gedëlleg Agenten gebaut. Fir de Moment ass et privat, an enger zouener Alpha mat Frënn. Wëlls du et probéieren, wann et opgeet?","join.btn":"Interessi umellen","join.small":"Mir schreiwen dir eng E-Mail, soss näischt","footer.tag":"AI-gile. Keng Tracker, keng Cookien, kee Stand-up-Kaffi.","footer.licence":"Geschäftslizenz","footer.status":"Status","footer.privacy":"Wat mir behalen","footer.thanks":"Uriff dank ChilledChat","form.sending":"Gëtt geschéckt…","form.failed":"Dat huet net geklappt: probéier et méi spéit nach eng Kéier.","form.offline":"AI-gile war net z'erreechen: probéier et méi spéit nach eng Kéier.","form.keep":"Mir benotzen dat nëmmen, fir dir ze äntweren, an dann läsche mir et. Keng Tracker, keng Cookien.","form.keepLink":"Wat mir behalen","interest.title":"AI-gile: sot mer Bescheed, wann d'Alpha opgeet","interest.description":"Looss deng E-Mail do, fir ze héieren, wann d'zouene Alpha oder Beta vun AI-gile opgeet.","interest.h1":"🔔 Sot mer Bescheed, wann et opgeet","interest.lede":"AI-gile ass an der zouener Pre-Alpha. Looss deng E-Mail do, a mir schreiwe ee Mol, wann et e Plaz fir dech gëtt.","interest.email":"Deng E-Mail","interest.which":"Wéi een Test?","interest.alpha":"Zouen Alpha: fréi, rau, vill Ännerungen","interest.beta":"Beta: méi roueg, méi spéit","interest.both":"Egal wéi eng, déi als Éischt kënnt","interest.submit":"Setz mech op d'Lëscht","interest.thanks":"Merci! Du bass op der Lëscht.","licence.title":"AI-gile: Geschäftslizenz","licence.description":"Benotz du AI-gile an dengem Geschäft? Frot eng gratis Geschäftslizenz un.","licence.h1":"📜 Geschäftslizenz","licence.lede":"Benotz du AI-gile op der Aarbecht? Sot eis, wien s du bass a wat s du méchs. Wann et eppes Gutts bewierkt, ass d'Lizenz gratis.","licence.company":"Firma","licence.website":"Websäit","licence.what":"Wat s du méchs","licence.how":"Wéi et der Welt hëlleft","licence.email":"E-Mail","licence.submit":"Umellen","licence.thanks":"Merci! Mir äntweren per E-Mail.","status.title":"AI-gile-Status","status.h1":"AI-gile-Status","status.quiet":"Alles roueg","status.intro":"Funktionéiert AI-gile grad? Dës Säit kontrolléiert all 5 Minutten d'Websäit, d'Deele vun Tafelen, d'Uriff an den Download.","status.up":"Funktionéiert (huet an {ms} ms geäntwert)","status.slow":"Huet op déi lescht Kontroll net geäntwert, probéiert et nach eng Kéier","status.down":"Ausgefall: huet op déi lescht zwou Kontrollen net geäntwert","status.svc.web":"Websäit","status.svc.web.offers":"Dës Säit: wat AI-gile ass, an den Interessi-Formulaire","status.svc.boards":"Tafelen deelen","status.svc.boards.offers":"Ëffentlech Tafelen, Messagen tëscht Frënn an Invitatiounen","status.svc.calls":"Uriff","status.svc.calls.offers":"Stëmm, Video an Ecran deelen an AI-gile","status.svc.download":"Download","status.svc.download.offers":"De Windows-Installateur an Invitatiounslinken","status.checking":"Gëtt kontrolléiert…","status.offline":"De Statusservice ass de Moment net z'erreechen (probéiert et nach eng Kéier)","status.updated":"aktualiséiert {ago}","status.justNow":"grad elo","status.min":"viru {n} Min.","status.hours":"viru {n} Std.","status.days":"viru {n} Deeg","privacy.title":"AI-gile: wat mir behalen","privacy.h1":"Wat mir behalen","privacy.lede":"Kuerz gesot: nëmmen dat, wat s du eis schécks, an net laang.","privacy.only":"Nëmmen dat, wat s du eis schécks: wat s du an e Formulaire agëss, wéi deng E-Mail. Soss näischt iwwer dech.","privacy.sealed":"Et gëtt versigelt, sou datt eise Server et net liese kann: an dengem Browser, ier et fortgeet (op engem méi alen Browser, soubal et ukënnt). Nëmmen eis eege Tafel kann et opmaachen.","privacy.server":"Et gëtt vum Server geläscht, soubal et op eiser Tafel ukënnt. Alles, wat no 30 Deeg nach do ass, gëtt souwisou geläscht.","privacy.board":"Mir halen et nëmmen esou laang op eiser Tafel, bis mir dir geäntwert hunn, dann läsche mir et och do.","privacy.none":"Keng Tracker, keng Cookien, keng Analysen.","privacy.local":"Deng Sprooch an deng Wiel tëscht hell an donkel bleiwen an dengem eegene Browser. Si ginn eis ni geschéckt.","privacy.ask":"Wëlls du, datt et méi fréi ewech ass? Äntwer op eis E-Mail a so eis et.","live.h2":"Kuck zou, wéi et gebaut gëtt, live","live.caption":"All Kaart ass verstoppt: du gesäis d'Form vun der Aarbecht, net d'Wierder.","live.watching.one":"live: {n} kuckt","live.watching.other":"live: {n} kucken","live.last.now":"Lescht Kaart grad elo geréckelt","live.last.min.one":"Lescht Kaart viru {n} Minutt geréckelt","live.last.min.other":"Lescht Kaart viru {n} Minutte geréckelt","live.last.hour.one":"Lescht Kaart viru {n} Stonn geréckelt","live.last.hour.other":"Lescht Kaart viru {n} Stonne geréckelt","live.last.day.one":"Lescht Kaart viru {n} Dag geréckelt","live.last.day.other":"Lescht Kaart viru {n} Deeg geréckelt","live.offline":"D'Live-Board mécht eng kleng Paus. Kuck geschwë nees vir.","live.cols":"Backlog|Ze maachen|Amgaang|Team kontrolléiert|Fir dech zum Testen|Fir d'Team|Fäerdeg"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboteren.","Delegéiert."]},{"n":2,"texts":["Roboteren schaffen.","Agenten, organiséiert.","Iddien, gebaut."]},{"n":3,"texts":["Kanban fir Roboteren.","Iddie ginn Funktiounen.","Gratis Agent-Kanban."]},{"n":5,"texts":["Kanban-Tafel, vun Agenten ugedriwwen.","Du schreifs Kaarten. Agenten bauen.","Gratis, lokal, getest, e bësse domm."]},{"n":8,"texts":["Eng gratis Kanban-Tafel, op där KI-Agenten schaffen.","Schreif eng Iddi. Agenten bauen se. Du hëlls un.","Agile fir ee Mënsch a vill gedëlleg Roboteren."]},{"n":13,"texts":["Eng Kanban-Tafel op dengem Computer, där KI-Agenten d'Kaarten ofschaffen, während s du de Chef bleifs.","Schreif eng Iddi. E Team vun Agenten baut se. En Tester kontrolléiert se. Du seess Jo.","Keng Konten, keng Tracker: eng Tafel, e puer Roboteren an du, deen d'Say huet."]},{"n":21,"texts":["AI-gile ass eng Kanban-Tafel fir d'Zesummenaarbecht mat KI-Programméieragenten. Si huelen d'Kaarten, du testes se a hëlls se un.","All Projet kritt e Lead an e Team vun KI-Agenten. Kommentéier iergendeng Kaart, an d'Team mécht sech un d'Aarbecht.","Eng gratis, perséinlech To-do-Tafel, déi op dengem eegene Computer leeft. D'Aarbechter sinn Roboteren. Deen, dee Jo seet, bass du."]},{"n":34,"texts":["Du leess Iddie op eng Tafel. E Team vun KI-Agenten mécht se zu funktionéierende Funktiounen, testet se a gëtt se der zeréck, mat Schrëtt zum Probéieren. Näischt zielt als fäerdeg, bis du et seess.","AI-gile ass eng hausgemaachte Kanban-Tafel, déi de Rich mat vill Hëllef vun den Agenten gebaut huet, déi se elo verwalt. Si ass gratis, leeft op dengem Computer a gëtt mat Frënn gedeelt, net verkaaft.","Stell der eng ganz normal Kanban-Tafel vir, mat Kolonnen vu Backlog bis Done, nëmmen datt d'Kaarten vun KI-Agenten opgeholl ginn. Si bréngen Neiegkeeten, froen no, wa se festhänken, a waarden ëmmer op däin Daum no uewen."]},{"n":55,"texts":["AI-gile ass eng Kanban-Tafel, wou d'Team aus KI-Agenten besteet. All Projet huet e Lead, deen d'Aarbecht plangt, an Hëllefer, déi se bauen. Wann eng Funktioun prett ass, probéiert en KI-Tester se aus a mécht e Screenshot, duerno landet se an dengem Stapel. Huel se un, oder kommentéier, an d'Team schafft se nei.","Et huet ugefaange mat enger Persoun, déi vill KI-Programméiersessiounen op eemol am Bléck wollt behalen, a gouf zu enger richteger Tafel. Si leeft op dengem Computer, brauch kee Kont a läit keng Tracker un. Si ass gratis fir Frënn a fir all, deen nei giereg ass. Si ass nach net fäerdeg, also erwaart rau Kanten an heiansdo eng Iwwerraschung.","Hei ass déi éierlech Versioun. Du muss nach ëmmer d'Iddie hunn, an du muss d'Resultater nach ëmmer kontrolléieren. Wat AI-gile mécht, ass alles dertëscht: et hält d'Kaarten an der Rei, erweckt dee richtegen Agent, wann s du kommentéiers, weist genee, wat geännert gouf, a sammelt alles an engem kuerze Stapel fir dech."]},{"n":89,"texts":["AI-gile ass eng gratis Kanban-Tafel, déi s du op dengem eegene Computer lafe léiss. Amplaz vu Leit huet all Projet e Team vun KI-Agenten: e Lead, deen deng Iddien a Kaarten an e Plang ëmwandelt, an Hëllefer, déi d'Kaarten no Prioritéit ofschaffen. Wann eppes gebaut ass, geet en KI-Tester d'Testschrëtt duerch a weist dir, wat en gesinn huet. Dunn waart et an engem Stapel mam Numm Fir dech. Du hëlls et un, oder du kommentéiers, an d'Team probéiert et nach eng Kéier. Näischt kënnt ouni dech bei Done.","E puer Funktiounen, un déi s du vläicht net denks. Eng Nuechtwuecht hält d'Kolonn Ze maachen gefëllt, während s du schléifs, a wielt Kaarten aus, déi keng Äntwert vun dir brauchen. En Token-Zieler weist, wéi vill d'Agenten haut an dës Woch gebraucht hunn, an de No Token Mode seet hinnen, si sollen oppassen. Du kanns Frënn schreiwen, a privat Noriichte sinn Enn-zu-Enn verschlësselt. D'Tafel schwätzt ongeféier 120 Sproochen, dorënner Hollännesch, Flämesch, Piroten a Klingonesch. Näischt dovun kascht eppes, a keen probéiert dir et ze verkafen.","AI-gile ass e klengt, perséinlecht Projet, keng Firma. De Rich wollt e puer KI-Programméierprojete bedreien, ouni all App opzemaachen, fir no all ze kucken, also hunn hien an d'Agenten eng Tafel dofir gebaut an duerno mat där Tafel de Rescht vun hirem Selwer. Si ass an der zouener Pre-Alpha, dat heescht, si funktionéiert, meeschtens, fir eng Handvoll Frënn. Et gëtt keng Präisssäit, keen Newsletter a kee Wuesstemsplang. Wann et nëtzlech kléngt, kanns du froen, ob s du et probéiere kanns, wann et e bësse méi opgeet."]},{"n":144,"texts":["AI-gile ass eng Kanban-Tafel fir ee Mënsch a ganz vill KI-Agenten. Si leeft op dengem eegene Computer a ass komplett gratis. Du setz Projeten un, an all Projet kritt e Lead an e klengt Team. Du schwätz mam Lead, ongeféier wéi bei Discord, a beschreifs eng Iddi; de Lead mécht Kaarten an e Plang dorausser a waart dann, bis s du op Go dréckss. D'Team schafft d'Kaarten no Prioritéit of, mat enger einfacher Kommandozeil, déi fir Sproochmodeller gemaach ass. Ier eppes bei dech zeréckkënnt, geet en KI-Tester d'Schrëtt an enger Kopie vun der App duerch a mécht e Screenshot derbäi. Fäerdeg Aarbecht landet an dengem Stapel, mat de geännerten Dateien an dem Ënnerscheed. Du hëlls se un, oder du léiss e Kommentar, an d'Team erwächt a probéiert et nach eng Kéier. Nëmmen du kanns eng Kaart op Done réckelen. Alles dat leeft op dengem Computer, ouni Konten, ouni Tracker an ouni Cookien.","E Dag mat AI-gile, ongeféier. Owes léiss du e puer Kommentarer: dëse Knäppchen ass um falsche Plaz, déi Lëscht soll sortéiert sinn, kéinte mir en donkelen Design hunn. Du gees schlofen. D'Agenten liesen d'Kommentarer, maache d'Ännerungen, testen se a ginn se dir zeréck. Wann Ze maachen eidel gëtt, fëllt d'Nuechtwuecht et aus dem Backlog mat Kaarten, déi keng Äntwert vun dir brauchen. Moies ass do ee kuerze Stapel: e puer Froen an e puer Saachen zum Probéieren, jidd mat Schrëtt, déi e schläfrege Mënsch kann nogoen, an engem Screenshot, dee weist, datt et funktionéiert. Du klicks dech duerch, hëlls dat Gutt un a schéckss de Rescht zeréck. En Token-Zieler weist, wat dat alles gebraucht huet, an de No Token Mode ass fir schmuel Wochen do. Dann hues du Fréistuck, wou d'Agenten nach net kënne hëllefen. An der Zäit schaffe se virun, an du hues ëmmer dat lescht Wuert.","Als Éischt, wat AI-gile net ass. Et ass kee Startup, et ass net ze verkafen, a keen sammelt deng Daten. Et ass eng gratis Tafel, déi op dengem Computer leeft, ouni Konten, ouni Tracker an ouni Cookien. Wat et ass: eng ordentlech Plaz, fir all KI-Programméierprojet op eemol ze gesinn, mat engem Team vun Agenten, dat d'Kaarten ofschafft, an dir, deen d'Decisiounen trëfft. Et fält verwandte Kaarten zesummen, flécket duerchenee Titelen a passt op, datt de Code schlank bleift. Et schwätzt ongeféier 120 Sproochen, vum Hollännesche a Flämesche bis zu Piroten a Klingonesch. Frënn kënnen sech schreiwen, privat a verschlësselt. Et gouf vum Rich a ganz villen gedëlleg Agenten gebaut, meeschtens mat sech selwer. Et ass an der zouener Pre-Alpha, dofir ass et op e puer Plazen rau. Wann et nom Spaass kléngt, frot léif, a vläicht kënns du fréi eran."]}],"quips":{"1":"Ee Wuert. Mutteg. Vläicht ze mutteg.","3":"Dräi Wierder. Elo schonn éierlecher wéi déi meescht Produktsäiten.","8":"Aacht Wierder. Ëmmer nach méi kuerz wéi e Stand-up.","21":"D'Längte sinn iwwregens Story Points. Natierlech sinn et dat.","55":"Fënnefafofzeg Wierder. Zwou Kaarten si fäerdeg ginn, während s du dat gelies hues.","144":"Dat ass déi laang. Et gëtt keng 233. D'Agenten sinn schlofe gaang."}},"timeline":{"first-idea.name":"Déi éischt Iddi","first-idea.line":"Dat allereschte Gespréich, ier et iwwerhaapt Code gouf.","first-board.name":"Déi éischt Tafel","first-board.line":"Eng Tafel, déi hiren eegene Bau verfollegt: Kaarten, Kolonnen, Zéien an Ofleeën, Projeten.","team-roles.name":"Team a Rollen","team-roles.line":"Agent-Profiler, Team-Virlagen, Raim a wien wat mécht.","install.name":"Installatioun a Versiounen","install.line":"E Zip, deen e Frënd installéiere kann, Selwer-Updates, Kanäl an Zeréckrollen.","usage-saver.name":"Verbrauchsspuerer","usage-saver.line":"Moosse, wat d'Lafe kaschten, de Code schlank halen, däi Limit schounen.","friends.name":"Frënn a Deelen","friends.line":"Privat DMs, e verschlësselte Relay, Invitatiounen, Rollen a gedeelte Projeten.","languages.name":"Sproochen","languages.line":"All Bildschierm-Text an enger Sproochdatei, mat Hollännesch a Flämesch als Éischt.","ai-tester.name":"KI-Tester","ai-tester.line":"E Tester kontrolléiert all Iwwergab als Éischt a weist, wat en gesinn huet.","website.name":"D'Websäit","website.line":"aigile.lol, den Teaser an dës Zäitleescht.","streaming.name":"Chat a Streaming","streaming.line":"Discord, Twitch, OBS, Streamer-Modus, GIFs an Emojien.","no-ai.name":"Editioun ouni KI","no-ai.line":"Eng Tafel fir Leit, déi ouni KI programméieren, an ëffentlech Tafelen.","night-watch.name":"Nuechtwuecht","night-watch.line":"E Wuechter an e Scrum Master halen d'Teams um Rees, während s du schléifs.","p-more.name":"Alles anescht","p-more.line":"Méi kleng Iddien, déi nach drun sinn.","p-android.name":"Telefon an Android","p-android.line":"Erreech deng Tafel vum Telefon aus, duerno mat enger eegener Android-App.","p-release.name":"Alpha a méi wäit","p-release.line":"Zouen Alpha, déi live Säit, dunn Beta.","p-languages.name":"Méi Sproochen","p-languages.line":"130 Sproochen, an e Sprooch-Immersiounsmodus fir Léierender.","p-engines.name":"Méi KI-Motoren","p-engines.line":"Wiel Claude, Codex, Gemini, Copilot oder Cursor fir all Agent.","p-pro.name":"Professionell Praxis","p-pro.line":"Risiko-Etiketten, Merge-Paarten, Incident-Kaarten a Leitplanken.","p-self.name":"Op dech oppassen","p-self.line":"Midd-Modus, Self-Care-Erënnerungen a 4:20.","p-servers.name":"Serveren a Wuesstem","p-servers.line":"Global Serveroptiounen, Rollen a Planung fir de Wuesstem.","p-livestream.name":"Streaming-Extrae","p-livestream.line":"Twitch-Chat, eege Emojien an eng ëffentlech Live-Usiicht."},"words":{"button":"📖 Fachbegrëffer","h":"📖 Wierder erkläert","intro":"Gratis Training an einfacher Sprooch: all Wuert, dat s du begéines, vun enger éischter Iddi bis zu engem Service, op deen d'Leit sech verloossen, mat Agile, Bauen, Sécherheet a Schaffen mat KI ënnerwee.","search":"E Wuert sichen…","none":"Kee Wuert passt dozou.","close":"Zoumaachen","count":{"one":"{count} Wuert","other":"{count} Wierder"},"groups":[{"id":"idea","name":"💡 Iddi an Entdeckung"},{"id":"plan","name":"🗺️ D'Aarbecht plangen"},{"id":"agile","name":"🔁 Agil Aarbechtsweisen"},{"id":"build","name":"🛠️ Et bauen"},{"id":"test","name":"🧪 Testen a Qualitéit"},{"id":"change","name":"🔀 Et sécher änneren"},{"id":"run","name":"🛎️ E Service bedreiwen"},{"id":"sec","name":"🔒 Sécherheet a Dateschutz"},{"id":"ai","name":"🤖 Mat KI schaffen"},{"id":"money","name":"💰 Geld a Lizenzen"}],"list":[{"id":"discovery","g":"idea","word":"Discovery (Entdeckung)","text":"Déi fréi Phas, an där s du erausfënns, wéi ee Problem et wäert ass ze léisen a fir wien, ier eppes gebaut gëtt.","also":["Discovery-Phas","Entdeckungsphas"]},{"id":"problemstmt","g":"idea","word":"Problembeschreiwung","text":"Een oder zwee Sätz, déi soen, wien e Problem huet, wat et ass a firwat et wichteg ass, sou datt jiddereen op dat selwecht zielt.","also":["Problembeschreiwungen","Problem Statement"]},{"id":"user","g":"idea","word":"Notzer","text":"E Mënsch, deen notzt, wat s du baus. Seng Bedierfnesser sinn dat, wouerfir d'Aarbecht gemaach gëtt.","also":["Notzer","User","Benotzer"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Jiddereen, deem et net egal ass, wéi d'Aarbecht ausgeet, oder deen dovun betraff ass, wéi d'Leit, déi se bezuelen, notzen oder ënnerstëtzen.","also":["Stakeholders","Bedeelegt"]},{"id":"persona","g":"idea","word":"Persona","text":"Eng erfonne, awer realistesch Persoun, déi fir eng Zort Notzer steet, sou datt d'Team ka froen: „Géif de Sam dat einfach fannen?“","also":["Personas"]},{"id":"userresearch","g":"idea","word":"User Research","text":"Mat richtege Leit schwätzen an hinnen nokucken, fir ze léieren, wat se brauchen, amplaz ze roden.","also":["Notzer-Interviewen","User-Interviewen"]},{"id":"journey","g":"idea","word":"User Journey","text":"D'Schrëtt, déi e Mënsch geet, fir eppes fäerdegzebréngen, vum éischten Héieren dovun bis zum Schluss, och ausserhalb vun dengem Produkt. Wann s du et opzeechens, gesäis du, wou en hänke bleift.","also":["User Journeys","Customer Journey","Notzerrees"]},{"id":"painpoint","g":"idea","word":"Pain Point","text":"Eppes, wat d'Leit haut nervt oder ophält. Gutt Produkter huelen Pain Points ewech.","also":["Pain Points","Problempunkt"]},{"id":"assumption","g":"idea","word":"Unnam","text":"Eppes, wat s du gleefs, awer nach net nogepréift hues. Wann s du d'Unnamen opschreiws, gesäis du, wat s du fir d'éischt teste solls.","also":["Unnamen","Assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothes","text":"Deng bescht Schätzung, déi s du préiwe wëlls, mat deem, wat s du erwaars, wéi: „D'Leit mellen sech un, wann den éischte Mount gratis ass“.","also":["Hypothesen"]},{"id":"experiment","g":"idea","word":"Experiment","text":"E klenge geplangten Test, fir erauszefannen, ob eng Iddi funktionéiert, ier s du vill drop setz.","also":["Experimenter"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of Concept (PoC)","text":"E séiere, grobe Versuch, fir ze gesinn, ob eng Iddi iwwerhaapt funktionéiere kann. Meeschtens gëtt en ewechgehäit, soubal s du d'Äntwert hues.","also":["PoC","Proof of Concept"]},{"id":"prototype","g":"idea","word":"Prototyp","text":"E fréie Modell vum Produkt, dacks klickbar Biller, fir d'Iddi bei de Leit ze probéieren, ier s du et richteg baus.","also":["Prototypen","Prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Eng einfach Skizz vun engem Bildschierm, déi weist, wou wat higehéiert, ouni Faarwen an ouni richtegen Inhalt.","also":["Wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"E genaut Bild dovun, wéi e Bildschierm ausgesäit, mat richtege Faarwen an Texter, awer et funktionéiert nach näischt.","also":["Mockups","Mock-up","Mock-ups"]},{"id":"bizcase","g":"idea","word":"Business Case","text":"D'Grënn fir e Projet ze maachen: wat en kascht, wat en abréngt oder spuert, an d'Risiken.","also":["Business Cases"]},{"id":"feasibility","g":"idea","word":"Machbarkeet","text":"Ob eppes mat der Zäit, dem Geld an de Kompetenzen, déi s du hues, wierklech ka gebaut an ënnerhale ginn.","also":["machbar","Feasibility"]},{"id":"outcome","g":"idea","word":"Outcome (Resultat)","text":"D'Ännerung, déi s du fir d'Leit wëlls, wéi manner verpasste Rendez-vousen. Si ass méi wichteg, wéi wéivill s du baus.","also":["Outcomes","Resultater"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Eppes, wat d'Team mécht, wéi en neie Bildschierm oder e Rapport. Datt et gemaach ass, heescht net automatesch, datt et iergendengem hëlleft.","also":["Outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Erfollegszuel","text":"Eng Zuel, déi dir seet, ob d'Aarbecht gemaach huet, wouerfir se do war, wéi méi Leit, déi hir Bestellung ofschléissen.","also":["Erfollegszuelen","Success Metric","Success Metrics"]},{"id":"kpi","g":"idea","word":"Key Performance Indicator (KPI)","text":"Eng wichteg Zuel, déi s du am Aa behäls, fir ze gesinn, ob alles gutt leeft, wéi Umeldunge pro Woch.","also":["KPI","KPIs","Key Performance Indicator","Kennzuel"]},{"id":"okr","g":"idea","word":"Objectives and Key Results (OKRs)","text":"Eng Manéier, Ziler ze setzen: den Objective seet, wat s du wëlls, an e puer Key Results sinn d'Zuelen, déi weisen, datt s du et gepackt hues.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produkt","text":"Dat, wat fir seng Notzer gebaut an ënnerhale gëtt, wéi eng App, eng Websäit oder en Tool.","also":["Produkter"],"noTip":1},{"id":"vision","g":"plan","word":"Produktvisioun","text":"Eng kuerz Ausso doriwwer, wiem d'Produkt hëlleft a wou et laangfristeg higeet.","also":["Visiounsstatement","Vision Statement"]},{"id":"po","g":"plan","word":"Product Owner (PO)","text":"D'Persoun, déi entscheet, wat gebaut gëtt an a wéi enger Reiefolleg, sou datt d'Team ëmmer un deem schafft, wat am wichtegsten ass. Bei AI-gile bass dat du.","also":["PO","Product Owners"]},{"id":"pm","g":"plan","word":"Product Manager (PM)","text":"D'Persoun, déi sech ëm d'Richtung vun engem Produkt këmmert: wéi eng Problemer et léist, fir wien a firwat. PM kann och Projetsleeder heeschen, also kuck no, wat gemengt ass.","also":["Product Managers"]},{"id":"projmgr","g":"plan","word":"Projetsleeder","text":"D'Persoun, déi e Projet an der Zäit an am Budget hält a verfollegt, wien wat bis wéini mécht.","also":["Projetsleeder","Project Manager","Project Managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"E grobe Plang vun deem, wat an de nächste Méint kënnt, an der Reiefolleg. E weist d'Richtung, keng genau Datumen, a gëtt ugepasst, soubal s du méi gewuer gëss.","also":["Roadmaps"]},{"id":"milestone","g":"plan","word":"Meilesteen","text":"E Punkt an engem Projet, deen et wäert ass ze markéieren, wéi „éischt Versioun online“ oder „100 Notzer“.","also":["Meilesteng","Milestone","Milestones"]},{"id":"mvp","g":"plan","word":"Minimum Viable Product (MVP)","text":"Déi klengst Versioun vun engem Produkt, déi nach ëmmer fir richteg Leit nëtzlech ass, sou datt s du fréi vun hinne kanns léieren.","also":["MVP","MVPs","Minimum Viable Product"]},{"id":"requirement","g":"plan","word":"Ufuerderung","text":"Eppes, wat dat fäerdegt Produkt muss kënnen oder sinn.","also":["Ufuerderungen","Requirement","Requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope (Ëmfang)","text":"Wat an der Aarbecht dran ass an, genausou wichteg, wat net.","also":["am Scope","ausserhalb vum Scope","Ëmfang"]},{"id":"scopecreep","g":"plan","word":"Scope Creep","text":"Wann no an no ëmmer méi bei d'Aarbecht kënnt, ouni datt sech een iwwer déi extra Zäit oder Käschte geeënegt huet, sou datt se ni ganz fäerdeg gëtt.","also":["Feature Creep"]},{"id":"feature","g":"plan","word":"Feature","text":"Eng Saach, déi d'Produkt fir d'Leit ka maachen, wéi „däi Passwuert zrécksetzen“.","also":["Features","Funktioun"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"E grousst Stéck Aarbecht, ze grouss fir op eemol, dofir gëtt et a méi kleng Kaarten opgedeelt.","also":["Epics"]},{"id":"story","g":"plan","word":"User Story","text":"E klengt Stéck Aarbecht, aus der Vue vum Notzer geschriwwen: „Als Clientin wëll ech mäi Kuerf späicheren, fir spéider weidermaachen ze kënnen.“ Dat bréngt d'Gespréich doriwwer an de Gang, wat gebaut soll ginn.","also":["User Stories","Notzerstory"]},{"id":"ac","g":"plan","word":"Akzeptanzkritären (AC)","text":"D'Kontrollen, déi eng Kaart muss bestoen, fir als fäerdeg ze zielen, virum Ufank ofgemaach, wéi „de Kuerf ass nach do, nodeems ech mech of- an nees ugemellt hunn“.","also":["Akzeptanzkritär","Acceptance Criteria"]},{"id":"task","g":"plan","word":"Aufgab","text":"Eng eenzel Aarbecht, déi ze maache ass, dacks e klenge Schrëtt vun enger gréisserer Story.","also":["Aufgaben","Task","Tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"En anert Wuert fir eng Kaart: ee Stéck Aarbecht oder eng Ufro, vum Ufank bis zum Enn verfollegt.","also":["Tickets"]},{"id":"priority","g":"plan","word":"Prioritéit","text":"Wéi wichteg oder dréngend eppes am Verglach mat allem anerem ass, sou datt déi wichtegst Aarbecht als éischt drun kënnt.","also":["Prioritéiten","Priority","Priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioriséierung","text":"D'Aarbecht no Wichtegkeet an eng Reiefolleg bréngen. Eng üblech Method ass MoSCoW: Must have, Should have, Could have, Won't have this time.","also":["prioriséieren","Prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Schätzung","text":"Déi bescht Schätzung, wéi grouss oder wéi laang e Stéck Aarbecht ass. Et ass eng Schätzung, kee Verspriechen.","also":["Schätzungen","Estimate","Estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story Points","text":"Eng Manéier, d'Gréisst vun der Aarbecht ze schätzen, andeems een d'Kaarten openee vergläicht („ongeféier duebel sou grouss wéi déi do“) amplaz a Stonnen. Si sinn net do, fir Teame matenee ze vergläichen.","also":["Story Point"]},{"id":"tshirt","g":"plan","word":"T-Shirt-Gréissten","text":"D'Gréisst vun der Aarbecht als S, M, L oder XL schätzen. Séier a gutt genuch fir déi fréi Planung.","also":["T-Shirt Sizing","T-Shirt Sizes"]},{"id":"poker","g":"plan","word":"Planning Poker","text":"E Spill fir ze schätzen: jiddereen weist zur selwechter Zäit eng Gréisst-Kaart, dann erklären deen Héchsten an deen Niddregsten, firwat.","also":["Scrum Poker"]},{"id":"dependency","g":"plan","word":"Ofhängegkeet","text":"Wann ee Stéck Aarbecht net ufänke oder fäerdeg ginn ka, bis en anert fäerdeg ass.","also":["Ofhängegkeeten","Dependency","Dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Alles, wat d'Aarbecht grad ophält, wéi eng Äntwert, déi feelt, oder en Tool, dee futti ass.","also":["Blockeren","Blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"Den Datum, bis wéini eppes muss fäerdeg sinn.","also":["Deadlines","Ofgabedatum"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable (Liwwerung)","text":"Eppes Konkretes, wat d'Aarbecht erstellt an iwwerreecht, wéi eng funktionéierend Säit oder e Rapport.","also":["Liwwerungen","Deliverable","Deliverables"]},{"id":"forecast","g":"plan","word":"Prognos","text":"Eng Viraussoen doriwwer, wat wahrscheinlech geschitt, wéi wéini d'Aarbecht fäerdeg ass, baséiert op deem, wat s du bis elo weess.","also":["Prognosen","Forecast","Forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metrik","text":"Alles, wat s du iwwer d'Zäit moss a verfolls, wéi Säitebesicher oder wéi laang eng Reparatur dauert.","also":["Metriken","Metric","Metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Dat, wat d'Leit dir iwwer deng Aarbecht soen, gutt a schlecht. Et fréi an dacks ze kréien ass d'Häerz vun Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"D'Waardelëscht vun Iddien an Aarbecht, déi nach net ageplangt sinn, dat Wichtegst uewen. Do gëtt näischt gemaach, bis et op Ze maachen geréckelt gëtt."},{"id":"sprint","g":"agile","word":"Sprint","text":"E kuerze, festen Zäitraum vun Aarbecht (dacks eng oder zwou Wochen, ni méi wéi e Mount) mat engem Zil an engem ofgemaachte Set vu Kaarten, déi fäerdeg solle ginn.","also":["Sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"E séiere Check-in all Dag: wat all Teammember gemaach huet, wat en als nächst mécht, a wat en ophält. Am Scrum heescht et den Daily Scrum.","also":["Standup","Stand-ups","Daily Scrum","Daily Stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Eng Aarbechtsweis, wou Kaarten iwwer d'Kolonne vun engem Board wanderen (wéi Ze maachen, Amgaang, Fäerdeg) an d'Team limitéiert, wéi vill op eemol amgaang ass, sou datt d'Aarbecht am Fluss bleift."},{"id":"wip","g":"agile","word":"WIP-Limit","text":"WIP ass d'Kuerzform vu Work in Progress. E WIP-Limit ass déi héchst Zuel u Kaarten, déi eng Kolonn op eemol soll hunn, sou datt d'Team Saachen ofschléisst, ier et Neies ufänkt.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Dem Team seng kuerz Checklëscht dofir, wat „fäerdeg“ heescht, wéi getest an erkläert, ier eng Kaart dir iwwerginn gëtt. Hiren Zwilling, d'Definition of Ready, seet, wéini eng Kaart kloer genuch ass, fir unzefänken.","also":["Definition of Ready","DoD","DoR","Fäerdegkeetsdefinitioun"]},{"id":"retro","g":"agile","word":"Réckbléck","text":"E regelméissege Réckbléck op d'Aarbechtsweis vum Team, fir sech op eng oder zwou Saache fir d'nächst Kéier besser ze maachen eens ze ginn. Kuerzform vu Retrospektiv. Bei AI-gile proposéiert eng Retro eng Ännerung un der Aarbechtsweis vum Team, an du seess Go oder Nach net.","also":["Retro","Retrospektiv"]},{"id":"swarm","g":"agile","word":"Schwarm","text":"Alleguer op Deck: vill Leit loossen aner Aarbecht falen, fir zesummen eng dréngend Saach ze léisen, bis se geléist ass. Bei AI-gile hëlleft all Team un engem Projet, an déi aner Projete waarden esoulaang.","also":["Swarm","Swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Am Scrum d'Persoun, déi dem Team hëlleft, gutt ze schaffen: raumt ewech, wat se ophält, hält d'Reuniounen op Kurs a coacht gutt Gewunnechten, ouni engem ze commandéieren. Bei AI-gile erkennt de Lead Scrum Master Kaarten, déi hänke bliwwen sinn, stéisst d'Teamen un an erënnert dech un dat, wat waart, iwwer all Projet ewech.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Eng Aarbechtsweis a klenge Schrëtt: e bëssen bauen, dacks richteg Resultater weisen, aus deem léieren, wat d'Leit soen, an de Plang ënnerwee änneren, amplaz alles am Viraus ze plangen.","also":["Agile Entwécklung","agil Aarbechtsweisen"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"Eng kuerz Erklärung, déi Software-Entwéckler 2001 geschriwwen hunn. Si setzt d'Leit, funktionéierend Resultater, eng enk Zesummenaarbecht mat de Clienten an d'Reagéieren op Ännerungen iwwer schwéier Pläng a Pabeierkrom.","also":["Manifesto for Agile Software Development","Agilt Manifest"]},{"id":"waterfall","g":"agile","word":"Waterfall (Waasserfall)","text":"Déi eeler Aarbechtsweis: alles plangen, dann alles bauen, dann alles testen, eng Etapp no där anerer. Ännerungen am spéiden Ablack si schwéier an deier.","also":["Waterfall-Modell","Waasserfall-Modell"]},{"id":"iteration","g":"agile","word":"Iteratioun","text":"Eng Ronn, an där eppes gebaut, kontrolléiert a verbessert gëtt. Agil Aarbecht ass eng Kette vun esou Ronnen, an e Sprint ass eng Zort dovun.","also":["Iteratiounen","Iteration","Iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"E neit funktionéierend Stéck, dat an engem Sprint oder enger Aarbechtsronn zum Produkt derbäikënnt a mat deem passt, wat scho virdru do war.","also":["Inkrementer","Increment","Increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Eng beléift agil Aarbechtsweis: e klengt Team schafft a kuerze Sprints op e Ziel hin, mat feste Rollen an e puer regelméissege Reunioune fir ze plangen, ze kontrolléieren an ze verbesseren."},{"id":"scrumteam","g":"agile","word":"Scrum-Team","text":"Déi kleng Grupp, déi am Scrum d'Aarbecht mécht: e Product Owner, e Scrum Master an d'Entwéckler.","also":["Scrum-Teamen","Scrum Team","Scrum Teams"]},{"id":"ceremonies","g":"agile","word":"Scrum-Eventer","text":"Déi regelméissege Reunioune am Scrum: Sprint-Planung, den Daily Scrum, d'Sprint-Review an d'Retro. Vill Leit nennen se Zeremonien.","also":["Zeremonien","Scrum-Zeremonien","Scrum Ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint-Planung","text":"D'Reunioun um Ufank vun engem Sprint, an där d'Team sech eens gëtt, firwat de Sprint wichteg ass, wéi eng Kaarten et iwwerhëlt a wéi et unfänkt.","also":["Planungsmeeting","Sprint Planning"]},{"id":"sprintgoal","g":"agile","word":"Sprint-Zil","text":"Ee Saz, deen seet, wouerfir e Sprint do ass. Kleng Aufgabe kënnen ënnerwee änneren, soulaang d'Zil erreecht gëtt.","also":["Sprint-Ziler","Sprint Goal","Sprint Goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint-Backlog","text":"D'Kaarten, déi fir de lafende Sprint erausgesicht goufen, mam Plang vum Team, wéi se ofgeschafft ginn.","also":["Sprint-Backlogs","Sprint Backlog"]},{"id":"productbacklog","g":"agile","word":"Product-Backlog","text":"Déi komplett, gerangte Lëscht vun allem, wat fir d'Produkt kéint gebaut ginn, dat Wichtegst uewen. Si ännert sech ëmmer erëm, soubal s du méi gewuer gëss.","also":["Product-Backlogs","Product Backlog"]},{"id":"productgoal","g":"agile","word":"Produktzil","text":"Dat gréissert Resultat, op dat d'Produkt hischafft, an dat dem Team hëlleft z'entscheeden, wat als nächst kënnt.","also":["Produktziler","Product Goal"]},{"id":"refinement","g":"agile","word":"Backlog-Refinement","text":"De Backlog regelméisseg duerchgoen, fir Kaarten opzeräumen, opzedeelen, ze zortéieren an ze detailléieren, sou datt se prett sinn, fir opgeholl ze ginn. Och Backlog Grooming genannt.","also":["Backlog Grooming","Refinement","Backlog Refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint-Review","text":"Eng Reunioun um Enn vun engem Sprint, an där d'Team weist, wat et fäerdeg krut, an héiert, wat d'Leit dovunner halen, fir z'entscheeden, wat als nächst kënnt.","also":["Sprint-Reviewen","Sprint Review"]},{"id":"demo","g":"agile","word":"Demo","text":"Fäerdeg Aarbecht live a funktionéierend deene Leit weisen, déi se bestallt hunn.","also":["Demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"E festgeluechte Quantum Zäit fir eppes. Wann en eriwwer ass, hält ee op, och wann net alles fäerdeg ass.","also":["Timeboxen","timeboxed","Zäitrahmen"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Wéi vill Aarbecht en Team normalerweis an engem Sprint fäerdeg kritt, fir ze plangen, wéi vill et déi nächst Kéier iwwerhëlt. Et ass keng Note dofir, wéi haart d'Leit schaffen.","also":["Team-Velocity","Team Velocity"]},{"id":"capacity","g":"agile","word":"Kapazitéit","text":"Wéi vill Aarbecht d'Team an enger Period iwwerhuele kann, wann Congéen an aner Aufgaben ofgerechent sinn.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-Chart","text":"E Diagramm, op deem d'Aarbecht, déi an engem Sprint nach iwwreg ass, vun Dag zu Dag erofgeet. Wann d'Linn flaach bleift, hänkt eppes fest.","also":["Burndown","Burn-down-Chart","Burndown Chart"]},{"id":"burnup","g":"agile","word":"Burnup-Chart","text":"E Diagramm vun der fäerdeger Aarbecht, déi mat der Zäit eropgeet, nieft der gesamter geplangter Aarbecht, sou datt s du gesäis, wéini s du do bass.","also":["Burnup","Burn-up-Chart","Burnup Chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban-Board","text":"De Board selwer: eng Kolonn fir all Etapp vun der Aarbecht, mat Kaarten, déi driwwer wanderen.","also":["Kanban-Boards","Kanban Board"]},{"id":"pullsys","g":"agile","word":"Pull-System","text":"Eng Aarbechtsweis, wou nei Aarbecht eréischt ufänkt, wann een Plaz huet, fir se z'iwwerhuelen, amplaz datt se engem op e scho voll Teller gedréckt gëtt.","also":["Pull System","Pull-Prinzip","pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Wéi glat d'Aarbecht iwwer de Board geet. E gudde Flow heescht, datt d'Kaarte weiderwanderen, amplaz sech opzestapelen.","also":["Aarbechtsflow","Flow of Work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead Time","text":"Wéi laang et dauert, vun deem Moment un, wou een eppes freet, bis et fäerdeg ass.","also":["Lead Times","Duerchlafzäit"]},{"id":"cycletime","g":"agile","word":"Cycle Time","text":"Wéi laang eng Kaart brauch, vum Moment un, wou wierklech drun geschafft gëtt, bis se fäerdeg ass.","also":["Cycle Times","Zyklus-Zäit"]},{"id":"throughput","g":"agile","word":"Throughput (Duerchsaz)","text":"Wéi vill Kaarten an enger Woch, oder an enger anerer festgeluechter Zäit, fäerdeg ginn.","also":["Duerchsaz","Throughput-Rate","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Fläschenhals","text":"Déi eng Etapp, wou d'Aarbecht sech opstapelt an alles dohannert bremst, wéi de schmuelen Hals vun enger Fläsch.","also":["Fläschenhäls","Bottleneck","Bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Eng Rei iwwer de Board, déi Kaarte vun enger Zort zesummefaasst, wéi dréngend Aarbecht oder d'Kaarte vun engem Team.","also":["Swimlanes","Swim Lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Eng Aarbechtsweis, déi Verschwendung ewechhëlt (alles, wat dem Client net hëlleft) an d'Aarbecht am Fluss hält."},{"id":"waste","g":"agile","word":"Verschwendung","text":"Am Lean alles, wat Aarbecht kascht, awer dem Client net hëlleft, wéi waarden, Nobessere oder Saachen, déi keen notzt, ze bauen.","noTip":1},{"id":"kaizen","g":"agile","word":"Kontinuéierlech Verbesserung","text":"Ëmmer e bësse besser ginn duerch kleng, regelméisseg Ännerungen, an dann nokucken, ob se gehollef hunn. Retroe sinn eng Manéier, dat ze maachen. Och Kaizen genannt.","also":["Kaizen"]},{"id":"selforg","g":"agile","word":"Selwer organiséiert Team","text":"E Team, dat selwer entscheet, wéi et d'Aarbecht mécht, amplaz Schrëtt fir Schrëtt gesot ze kréien.","also":["selwer organiséiert","selbstorganiséiert","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Funktiounsiwwergräifend Team","text":"E Team, dat all d'Kompetenzen huet, déi et brauch, fir d'Aarbecht selwer fäerdegzebréngen, wéi Design, Bauen an Testen.","also":["funktiounsiwwergräifend","Cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"E kuerzt, zäitlech begrenzt Stéck Recherche, fir eng Fro ze beäntwerten, ier d'richteg Aarbecht ugaange gëtt.","also":["Spikes"]},{"id":"rework","g":"agile","word":"Nobesserung","text":"Aarbecht nach eng Kéier maachen, well se déi éischt Kéier net richteg war.","also":["Rework","Nobesserungen"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Weeër, Agile iwwer vill Teamen an enger grousser Organisatioun ze benotzen. SAFe (dat Scaled Agile Framework) ass e bekannt Beispill.","also":["Scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Den Dossier vum Projet mam Code a senger ganzer Geschicht u Commits. En ka bei dir um Computer sinn, op GitHub oder op béide Plazen.","also":["Repository"]},{"id":"branch","g":"build","word":"Branch","text":"Eng getrennte Linn vun Aarbecht am Code, fir Ännerunge kënne ze maachen, ouni d'Haaptversioun unzefaassen.","also":["Branches"]},{"id":"commit","g":"build","word":"Commit","text":"E gespäichert Snapshot vum Code, mat enger kuerzer Notiz, wat sech geännert huet. Du kanns ëmmer op een zréckgoen.","also":["Commits"]},{"id":"push","g":"build","word":"Push","text":"Deng gespäichert Snapshots (Commits) vun dësem Computer op déi gedeelt Kopie online, wéi GitHub, eropschécken, sou datt se geséchert sinn an anerer se kréie kënnen."},{"id":"merge","g":"build","word":"Merge","text":"D'Ännerunge vun engem Branch an en anere bréngen, meeschtens zréck an d'Haaptversioun."},{"id":"pr","g":"build","word":"Pull Request","text":"Froen, datt d'Ännerunge vun engem Branch kontrolléiert an an d'Haaptversioun zesummegefouert ginn. Verschidde Säite nennen et e Merge Request.","also":["PR","PRs","Merge Request"]},{"id":"refactor","g":"build","word":"Refactoring","text":"De Code opraumen, ouni dass sech ännert, wat e mécht: méi kleng Dateien, méi kloer Nimm, manner Widderhuelung."},{"id":"bug","g":"build","word":"Bug","text":"Eppes, wat net esou funktionéiert, wéi et sollt.","also":["Bugs"]},{"id":"peerreview","g":"build","word":"Peer-Review","text":"E zweet Paar Aen: een anere wéi den Auteur kontrolléiert d'Aarbecht, ier se bei dech kënnt, sou datt manner Feeler duerchrutschen. Bei AI-gile kontrolléiert eng aner KI all Kaart.","also":["Code-Review","Peer Review"]},{"id":"code","g":"build","word":"Code","text":"Déi geschriwwen Uweisungen, déi engem Computer soen, wat e maache soll. Och Quellcode genannt.","also":["Quellcode","Source Code"],"noTip":1},{"id":"proglang","g":"build","word":"Programméiersprooch","text":"Eng Sprooch fir Code ze schreiwen, wéi JavaScript, Python oder Java. Verschidde passen fir verschidden Aufgaben.","also":["Programméiersproochen","Programming Language"]},{"id":"developer","g":"build","word":"Entwéckler (Dev)","text":"Een, dee Code schreift an ännert. Och Programméierer oder Software Engineer genannt.","also":["Entwéckler","Developer","Developers","Programméierer","Software Engineer"]},{"id":"software","g":"build","word":"Software","text":"Programmer, déi op Computeren an Telefone lafen, am Géigesaz zu de Maschinne selwer (der Hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Kuerzform vun Applikatioun: e Programm, deen d'Leit notzen, fir eppes gedoen ze kréien, um Telefon, um Computer oder am Webbrowser.","also":["Apps","Applikatioun","Applikatiounen","Application"],"noTip":1},{"id":"webapp","g":"build","word":"Web-App","text":"Eng App, déi an engem Webbrowser leeft, dofir muss näischt installéiert ginn.","also":["Web-Apps","Web App","Webapplikatioun"]},{"id":"frontend","g":"build","word":"Front-end","text":"Deen Deel vun enger App, deen s du gesäis an op deen s du klicks: d'Bildschiermer, d'Knäppercher an d'Wierder, dacks an dengem Browser.","also":["Frontend","Front End"]},{"id":"backend","g":"build","word":"Back-end","text":"Deen Deel vun enger App hannert de Kulissen, deen d'Daten hält an d'Aarbecht mécht, wann s du op eppes klicks, wéi däi Passwuert ze kontrolléieren.","also":["Backend","Back End"]},{"id":"fullstack","g":"build","word":"Full Stack","text":"Souwuel um Front-end wéi um Back-end schaffen.","also":["Full-Stack"]},{"id":"ui","g":"build","word":"Benotzerinterface (UI)","text":"Dat, wat e Mënsch um Bildschierm gesäit a benotzt: Layout, Knäppercher, Menüen an Text.","also":["UI","User Interface","Benotzerfläch"]},{"id":"ux","g":"build","word":"User Experience (UX)","text":"Wéi et sech ufillt, eppes ze benotzen: einfach, kloer a flott, oder verwierrend a lues.","also":["UX","Notzererlief","User Experience"]},{"id":"accessibility","g":"build","word":"Barrièrefräiheet (a11y)","text":"Saachen esou maachen, datt jiddereen se benotze kann, och Leit, déi net gutt gesinn, keng Maus benotze kënnen oder e Screenreader notzen.","also":["a11y","Accessibility","Zougänglechkeet"]},{"id":"responsive","g":"build","word":"Responsive Design","text":"Säiten esou maachen, datt se op all Bildschiermgréisst passen a gutt funktionéieren, vum Telefon bis zum grousse Monitor.","also":["responsiv"]},{"id":"designsys","g":"build","word":"Design-System","text":"E gemeinsame Kit vu Faarwen, Schrëften, Knäppercher a Reegelen, sou datt all Bildschierm gläich ausgesäit a sech gläich verhält.","also":["Design-Systemer","Design System","Design Systems"]},{"id":"architecture","g":"build","word":"Architektur","text":"Déi allgemeng Form vun engem System: wat d'Haaptdeeler sinn a wéi se matenee schwätzen."},{"id":"database","g":"build","word":"Datebank (DB)","text":"Eng organiséiert Späicherplaz fir Informatiounen, wéi eng ganz mächteg Tabell, déi d'App ka liesen an änneren.","also":["Datebank","Datebanken","Database","Databases","DB"]},{"id":"schema","g":"build","word":"Datebankschema","text":"De Plang vun enger Datebank: wéi eng Tabelle mat Informatioune se huet a wat an all eenzel drakënnt.","also":["Schema","Database Schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kuerzform vu Structured Query Language: d'Sprooch, mat där een a ville Datebanken no Informatioune freet oder se ännert.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Daten","text":"Informatiounen, déi e Computer gespäichert huet, wéi Nimm, Bestellungen oder Astellungen.","also":["Dateset","Datesets","Data","Dataset"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"E Computer, deen ëmmer un ass an op Ufroe vun anere Computeren äntwert, wéi eng Websäit ze schécken, wann s du se opmaachs.","also":["Serveren","Servers"]},{"id":"client","g":"build","word":"Client","text":"D'Säit, déi eppes freet, meeschtens däi Browser oder deng App, déi mat engem Server schwätzt. Am Geschäftsliewen heescht et och einfach Client, also Keefer.","also":["Clienten","Clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kuerzform vun Application Programming Interface: e feste Menü vun Ufroen, déi ee Programm un en anere stelle kann, wéi e Wiederdéngscht nom Wiederbericht fir haut ze froen.","also":["APIs","Application Programming Interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Ee Punkt um Menü vun enger API: eng Webadress, déi e Programm opruffe kann, fir eppes ze kréien oder ze schécken.","also":["Endpoints"]},{"id":"integration","g":"build","word":"Integratioun","text":"Zwee Systemer verbannen, sou datt se zesumme schaffen, wéi wann däi Geschäft Bestellungen un deng Comptabilitéits-Software schéckt.","also":["Integratiounen","Integration","Integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"E Message, deen ee System vu selwer un en anere schéckt, am Moment, wou eppes geschitt, wéi „Bezuelung kritt“.","also":["Webhooks"]},{"id":"library","g":"build","word":"Bibliothéik","text":"Fäerdege Code, deen een anere geschriwwen huet an deen s du nees benotze kanns, amplaz en selwer ze schreiwen.","also":["Bibliothéiken","Library","Libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Eng fäerdeg Struktur fir eng App ze bauen, déi vill dovunner festleet, wéi de Code opgebaut ass, wéi de Holzgerüst vun engem Haus, deen s du ausfëlls.","also":["Frameworks"]},{"id":"sdk","g":"build","word":"Software Development Kit (SDK)","text":"Eng Këscht mat Tools, Code a Beispiller, fir Software fir eng Plattform oder e Service ze bauen.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software-Ofhängegkeet","text":"Eng Bibliothéik oder en Tool, déi däi Code brauch, fir ze funktionéieren. Se um neiste Stand ze halen, ass wichteg fir d'Sécherheet.","also":["Software-Ofhängegkeeten","Software Dependency","Software Dependencies"]},{"id":"package","g":"build","word":"Package","text":"E Bündel fäerdege Code, deen s du an engem Projet installéieren a benotze kanns.","also":["Packagen","Packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package Manager","text":"En Tool, deen d'Packagen eroflued an aktualiséiert, vun deenen däi Code ofhänkt. npm ass e bekannten.","also":["Package Managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Dat meescht benotzt Tool, fir d'Geschicht vun de Code-Ännerungen ze halen, als Commits a Branchen."},{"id":"github","g":"build","word":"GitHub","text":"Eng Websäit, déi Git-Repos online hält, sou datt Teamen Code deelen, Ännerunge kontrolléieren an Aarbecht verfollege kënnen."},{"id":"vcs","g":"build","word":"Versiounskontroll","text":"Eng komplett Geschicht vun all Ännerung un de Fichieren halen, sou datt s du gesäis, wien wat geännert huet, an zréckgoe kanns, wann néideg. Git mécht dat.","also":["Source Control","Version Control","Version Control System","Versiounsverwaltung"]},{"id":"clone","g":"build","word":"Clone","text":"Deng eege voll Kopie vun engem Repo, mat senger Geschicht, op dengem Computer maachen.","also":["Clonen","Cloned","Cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Déi neiste Commits vun der gedeelter Kopie (wéi GitHub) op däi Computer huelen. D'Géigendeel vu Push.","also":["Git Pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main-Branch","text":"Déi offiziell Versioun vum Code, vun där jiddereen ausgeet, dacks main oder master genannt.","also":["Master-Branch","Main Branch","Master Branch"]},{"id":"conflict","g":"build","word":"Merge-Konflikt","text":"Wann zwou Ännerungen déiselwecht Zeilen op verschidde Manéieren änneren, sou datt de Computer se net zesummebréngt an e Mënsch muss wielen.","also":["Merge-Konflikter","Merge Conflict","Merge Conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Eng Usiicht, déi genee weist, wat sech tëscht zwou Versioune geännert huet: Zeilen, déi derbäikomm sinn, a Zeilen, déi ewech sinn.","also":["Diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Deng eege Kopie vum Repo vun engem aneren, déi s du ännere kanns, ouni sengen ze beaflossen.","also":["Forks","Forked"]},{"id":"script","g":"build","word":"Skript","text":"E kuerze Programm, deen eng Aarbecht vu selwer mécht, wéi Fichieren opzeräumen oder d'App ze starten.","also":["Skripter","Script","Scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"De Code an eppes ëmwandelen, wat prett ass fir ze lafen, oder dat fäerdegt Resultat selwer, dat ka lafen.","also":["Builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompiléieren","text":"Code, deen d'Leit geschriwwen hunn, an eng Form iwwersetzen, déi de Computer direkt ausféiere kann.","also":["Compile","Compiler","kompiléiert"]},{"id":"cli","g":"build","word":"Kommandozeil (CLI)","text":"E Textfënster, wou s du Uweisunge fir de Computer tipps, amplaz ze klicken. Och Terminal genannt.","also":["Command Line","Command-Line","CLI","Terminal","Kommandozeil"]},{"id":"config","g":"build","word":"Konfiguratioun (Config)","text":"D'Astellungen, déi bestëmmen, wéi Software sech verhält, getrennt vum Code gehalen, sou datt se einfach z'änneren sinn.","also":["Config","Configuration","Konfiguratioun"],"noTip":1},{"id":"envvar","g":"build","word":"Environment Variable","text":"Eng Astellung, déi engem Programm beim Start matgi gëtt, dacks fir Adressen oder Passwierder, sou datt se net am Code stinn.","also":["Environment Variables","Env Var","Ëmfeldvariabel"]},{"id":"debugging","g":"build","word":"Debugging","text":"Sichen, firwat eppes net funktionéiert, an et flécken.","also":["Debug","Debugged","Debuggen"]},{"id":"pairing","g":"build","word":"Pair Programming","text":"Zwee Leit (oder ee Mënsch an eng KI) schaffen zesumme um selwechte Code, een tippt an deen anere kontrolléiert.","also":["Pairing"]},{"id":"docs","g":"build","word":"Dokumentatioun (Docs)","text":"Geschriwwen Erklärungen, wéi eppes funktionéiert oder wéi ee et benotzt.","also":["Documentation","Docs","Dokumentatioun"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Deen éischte Fichier, deen s du an engem Repo liess: wat de Projet ass a wéi een en zum Lafe kritt.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy-System","text":"En eelere System, deen nach am Gebrauch ass an deen sech schwéier ännere léisst, dacks well nëmmen nach wéineg Leit e verstinn.","also":["Legacy-Systemer","Legacy Systems","Legacy Code","ale System"]},{"id":"techdebt","g":"build","word":"Technesch Schold","text":"Ofkierzungen, déi haut Zäit spueren, awer spéider Ännerungen méi lues maachen, wéi e Prêt, deen Zënse sammelt. Refactoring bezuelt en zeréck.","also":["Tech Debt","Technical Debt","technesch Scholden"]},{"id":"test","g":"test","word":"Test","text":"Eng Kontroll, ob eppes esou funktionéiert, wéi et soll. E puer Tester léisst de Computer vu selwer lafen, all Kéier wann de Code sech ännert; aner Tester sinn, datt s du eng fäerdeg Kaart probéiers, ier s du se akzeptéiers.","also":["Tester","Testen","testen"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kuerzform vu Quality Assurance: alles, wat gemaach gëtt, fir sécherzestellen, datt d'Aarbecht richteg ass, ier se online geet. Bei AI-gile heescht dat déi automatesch Kontrollen: wann QA rout ass, ass eppes feelgeschloen, an et kann net online goen, bis dat gefléckt ass.","also":["Qualitéitskontroll","Qualitéitssécherung"]},{"id":"testpile","g":"test","word":"Test-Stapel","text":"Déi fäerdeg Kaarten, déi drop waarden, datt s du se ausprobéiers, eng no der anerer. Akzeptéier eng oder schéck se mat enger Notiz zréck, an déi nächst kënnt.","also":["Test-Stapelen"]},{"id":"autotest","g":"test","word":"Automatiséierten Test","text":"Eng Kontroll, déi de Computer vu selwer mécht, all Kéier wann de Code sech ännert, fir Feeler fréi ze fannen.","also":["Automatiséiert Tester","Automated Test","Automated Tests","automatesch Tester"]},{"id":"manualtest","g":"test","word":"Manuellen Test","text":"E Mënsch, dee vun Hand probéiert, ob d'Aarbecht sech esou verhält, wéi se soll.","also":["Manuell Tester","Manual Test","Manual Testing","manuellt Testen"]},{"id":"unittest","g":"test","word":"Unit-Test","text":"Eng kleng automatesch Kontroll vun engem ganz klenge Stéck Code fir sech eleng.","also":["Unit-Tester","Unit Test","Unit Tests"]},{"id":"integtest","g":"test","word":"Integratiounstest","text":"Eng Kontroll, ob méi Deeler richteg zesumme funktionéieren, net nëmmen all eenzel fir sech.","also":["Integratiounstester","Integration Test","Integration Tests"]},{"id":"endtoend","g":"test","word":"End-to-End-Test (E2E)","text":"En Test, deen sech wéi e richtege Notzer vum Ufank bis zum Enn verhält, wéi sech umellen, kafen a bezuelen.","also":["E2E","End-to-End Tests"]},{"id":"uat","g":"test","word":"Benotzer-Ofnahmetest (UAT)","text":"Déi Leit, déi d'Aarbecht bestallt hunn, probéieren se selwer a soen, ob se mécht, wat se brauchen. D'Testlëscht vun AI-gile ass seng Versioun dovun.","also":["UAT","Acceptance Testing","Ofnahmetest","User Acceptance Testing"]},{"id":"regression","g":"test","word":"Regressioun","text":"Eppes, wat fréier funktionéiert huet, awer no enger Ännerung futti gaangen ass. Regressiounstester kontrolléieren, datt déi al Saache weider funktionéieren.","also":["Regressiounen","Regression","Regressions","Regressiounstest","Regressiounstester","Regression Test","Regression Testing"]},{"id":"smoke","g":"test","word":"Smoke-Test","text":"Eng ganz séier Kontroll, ob d'Haaptsaache iwwerhaapt funktionéieren, zum Beispill direkt nodeems eng Ännerung online geet. Wann et feelschléit, hal un a kuck no.","also":["Smoke-Tester","Smoke Test","Smoke Tests"]},{"id":"exploratory","g":"test","word":"Exploratorescht Testen","text":"D'Produkt fräi probéieren an et op verschidde Manéieren op d'Prouf stellen, fir Problemer ze fannen, déi geplangte Kontrollen iwwersinn géifen.","also":["Exploratory Testing","Exploratory Test","Exploratory Tests","Entdeckungstest"]},{"id":"testcase","g":"test","word":"Testfall","text":"E geschriwwene Szenario, deen ee probéiert: d'Schrëtt, an dat, wat soll geschéien.","also":["Testfäll","Test Case","Test Cases"]},{"id":"coverage","g":"test","word":"Test-Ofdeckung","text":"Wéi vill vum Code vun automatesche Tester kontrolléiert gëtt. Méi ass normalerweis méi sécher, awer eng héich Ofdeckung eleng beweist net, datt et gutt funktionéiert.","also":["Code Coverage","Testofdeckung"]},{"id":"testdata","g":"test","word":"Testdaten","text":"Erfonne Beispillinformatiounen, déi beim Testen benotzt ginn, sou datt keng privat Detailer vu richtege Leit ausgesat ginn.","also":["Test Data","Test Fixtures"]},{"id":"edgecase","g":"test","word":"Grenzfall","text":"Eng ongewéinlech Situatioun um Rand, wéi en eidele Formulaire oder en Numm mat engem Apostroph, wou dacks eppes futti geet.","also":["Grenzfäll","Edge Case","Edge Cases"]},{"id":"happypath","g":"test","word":"Happy Path","text":"De normale Wee, wou alles richteg leeft. Bei guddem Testen probéiert een och déi onglécklech Weeër."},{"id":"perftest","g":"test","word":"Performance-Test","text":"Kontrolléieren, wéi séier eppes ass a wéi gutt et mat Belaaschtung ëmgeet.","also":["Performance-Tester","Performance Testing","Performance Test","Performance Tests"]},{"id":"loadtest","g":"test","word":"Laaschttest","text":"Kontrolléieren, wéi e System domat ëmgeet, wann ganz vill Leit en op eemol benotzen.","also":["Laaschttester","Load Testing","Load Test","Load Tests"]},{"id":"sectest","g":"test","word":"Sécherheetstest","text":"No Schwaachstelle sichen, déi et engem erlabe kéinten, e System ze mëssbrauchen oder ze gesinn, wat een net soll.","also":["Sécherheetstester","Security Testing","Security Test","Security Tests"]},{"id":"accesstest","g":"test","word":"Barrièrefräiheetstest","text":"Kontrolléieren, datt Leit mat ënnerschiddleche Fäegkeeten d'Produkt benotze kënnen, och mat engem Screenreader oder nëmme mat der Tastatur.","also":["Barrièrefräiheetstester","Accessibility Testing","Accessibility Test"]},{"id":"linting","g":"test","word":"Linting","text":"Eng automatesch Kontroll, déi wahrscheinlech Feeler an en onordentleche Stil am Code fënnt, wéi eng Rechtschreiwkontroll fir Programmer.","also":["Linter","Lint"]},{"id":"static","g":"test","word":"Statesch Analys","text":"Code op Problemer kontrolléieren, andeems en automatesch gelies gëtt, ouni en auszeféieren.","also":["Static Analysis","Static Code Analysis","statesch Codeanalys"]},{"id":"flaky","g":"test","word":"Flaky Test","text":"En Test, deen heiansdo besteet an heiansdo duerchfält, ouni kloere Grond, dofir kann ee sech net ganz drop verloossen.","also":["Flaky Tests","onzouverlässeg Tester"]},{"id":"repro","g":"test","word":"Reproduzéieren (Repro)","text":"E Bug mat Absicht nees geschéie loossen, andeems ee déiselwecht Schrëtt follegt, sou datt e kann ënnersicht a behuewe ginn. Dës Schrëtt opzeschreiwen, ass dat Nëtzlechst an engem Bug-Rapport.","also":["Repro","Reproduce","Steps to Reproduce","Schrëtt zum Reproduzéieren"]},{"id":"severity","g":"test","word":"Schwéiergrad","text":"Wéi schlëmm d'Auswierkung vun engem Problem ass, vun engem klengen Ierger bis dohin, datt alles stoppt.","also":["Gravitéit","Severity","Severity Level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Eng nei Versioun vun der Software op d'Computere kopéieren, op deenen se leeft, wéi eng Testkopie oder de Live-Service."},{"id":"release","g":"change","word":"Verëffentlechung","text":"E benannte Pak vu fäerdeger Aarbecht, deen zesumme live geet, mat kuerzen Notizen iwwer dat, wat geännert huet. 🚀 Verëffentlechunge schreift d'Notizen aus de fäerdege Kaarten.","also":["Verëffentlechungen","Release"]},{"id":"rollback","g":"change","word":"Zréckrollen","text":"Op déi lescht Versioun zréckgoen, déi funktionéiert huet, wann eng nei Problemer mécht. Bei AI-gile sammelt Zréckrullen d'Undo-Schrëtt, déi bei all Ännerung opgeschriwwe sinn, an eng Checklëscht.","also":["Rollback","zréckgerollt"]},{"id":"live","g":"change","word":"Live","text":"Déi richteg Versioun, déi d'Leit notzen, am Géigesaz zu enger Kopie fir Saachen auszeprobéieren. Entwéckler soen och Produktioun dozou.","also":["Produktioun","production"],"noTip":1},{"id":"change","g":"change","word":"Ännerung","text":"Eng geplangten Ännerung un eppes, op dat d'Leit sech verloossen, als éischt opgeschriwwen: wat, firwat, de Risiko, wéini a wéi een et réckgängeg mécht. Fänk eng mat 🔀 Ännerung ufroen un.","also":["Ännerungen","Ännerungsufro"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Eppes, wat schif goe kéint, bewäert no deem, wéi wahrscheinlech an wéi schlëmm et wier. ⚠️ Risiken hält se an enger Lëscht, déi héchste Bewäertung fir d'éischt, all eenzel mat engem Datum fir nach eng Kéier nozekucken.","also":["Risiken","Risikoregister"]},{"id":"chgwin","g":"change","word":"Ännerungsfënster","text":"D'Zäiten, wou Ännerunge live goe dierfen, zum Beispill e rouegen Dënschdegowend. Ausserhalb vun enger Fënster kann eng Ännerungskaart net ofgeschloss ginn, ausser et ass en Noutfall.","also":["Ännerungsfënsteren","Change Window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Eng lescht Kontroll direkt, ier eng Ännerung online geet: all Persoun, déi muss zoustëmmen, seet Go oder No go. Et geet eréischt weider, wann jiddereen Go seet.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Genehmegung","text":"Op e Jo waarden, ier d'Aarbecht ufänkt. Eng Kaart, déi e Frënd opmécht, oder eng Ännerung, waart an ✅ Genehmegungen, bis s du se genehmegs oder ofleens.","also":["Genehmegungen"]},{"id":"quiettime","g":"change","word":"Rouzäit","text":"Eng Zäitspan, wéi wärend engem Livestream, enger Demo oder iwwer Nuecht, wou näischt online geet. D'Teame schaffen an teste weider, awer mam Online-Goe gëtt gewaart, bis se eriwwer ass. Soss heescht et en Change Freeze.","also":["Rouzäiten","Change Freeze","Ännerungsstopp"]},{"id":"devops","g":"change","word":"DevOps","text":"Eng Aarbechtsweis, wou d'Leit, déi Software bauen, an d'Leit, déi se bedreiwen, als ee Team schaffen, mat vill Automatiséierung, sou datt Ännerungen dacks a sécher online ginn."},{"id":"cicd","g":"change","word":"CI/CD (kontinuéierlech Integratioun a Liwwerung)","text":"D'Ännerunge vun allen ginn dacks an d'Haaptversioun zesummegefouert an all Kéier automatesch kontrolléiert (kontinuéierlech Integratioun), sou datt d'Software ëmmer prett ass, fir op Knäppchendrock online ze goen (kontinuéierlech Liwwerung).","also":["CI/CD","CI","CD","Continuous Integration","Continuous Delivery","kontinuéierlech Integratioun","kontinuéierlech Liwwerung"]},{"id":"contdeploy","g":"change","word":"Kontinuéierlecht Deployment","text":"Ee Schrëtt weider wéi kontinuéierlech Liwwerung: all Ännerung, déi d'Kontrolle bestanen huet, geet vu selwer online, ouni datt een e Knäppche muss drécken.","also":["Continuous Deployment","Continuous Deployments","kontinuéierlecht Ausrollen"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Déi automatesch Rei vu Schrëtt, déi eng Ännerung op hirem Wee online duerchleeft, wéi Build, Test, dann Deploy.","also":["Pipelines"]},{"id":"environment","g":"change","word":"Ëmfeld","text":"Eng getrennt Kopie vum System fir een Zweck, zum Beispill eng fir dran ze bauen, eng fir dran ze testen an déi live.","also":["Ëmfelder","Environment","Environments"],"noTip":1},{"id":"devenv","g":"change","word":"Entwécklungsëmfeld","text":"D'Kopie, an där en Entwéckler schafft, dacks op sengem eegene Computer, wou et kengem schued, wann eppes futti geet.","also":["Dev-Ëmfeld","Development Environment","Dev Environment"]},{"id":"testenv","g":"change","word":"Testëmfeld","text":"Eng getrennt Kopie vum System, déi nëmmen zum Testen benotzt gëtt, sou datt de richtege Service net ugeréiert gëtt.","also":["Testëmfelder","Test Environment","Test Environments"]},{"id":"staging","g":"change","word":"Staging","text":"Eng lescht Kopie, genee wéi de Live-System opgestallt, fir eng allerlescht Kontroll, ier eng Ännerung online geet.","also":["Staging-Ëmfeld","Staging Environment"]},{"id":"artifact","g":"change","word":"Build-Artefakt","text":"De Fichier oder de Bündel, deen e Build erstellt, prett fir gespäichert, kontrolléiert oder online gesat ze ginn.","also":["Build-Artefakter","Build Artifact","Build Artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Eng dréngend Reparatur, déi séier online gesat gëtt, ausserhalb vum normale Plang, well eppes Wichtegs futti ass.","also":["Hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"E klengen Update, deen e Bug behieft oder eng Sécherheetslück zoumécht. Sécherheetspatches séier z'installéieren, ass wichteg.","also":["Patches","Security Patch","Security Patches","Sécherheetspatch"]},{"id":"version","g":"change","word":"Versiounsnummer","text":"E Label wéi 2.4.1, dee seet, wéi eng Verëffentlechung s du hues. Dacks ännert sech déi éischt Zuel bei grousse Ännerungen an déi lescht bei klenge Reparaturen.","also":["Versiounsnummeren","Version Number","Version Numbers","Semantic Versioning"]},{"id":"relnotes","g":"change","word":"Release Notes","text":"Eng kuerz, einfach Lëscht vun deem, wat sech an enger Verëffentlechung geännert huet, fir d'Leit, déi se benotzen, mat Reparaturen a bekannte Grenzen. Och Changelog genannt.","also":["Changelog","Change Log","Verëffentlechungsnotizen"]},{"id":"flag","g":"change","word":"Feature-Flag","text":"E Schalter fir eng Funktioun un an aus, sou datt nei Aarbecht verstoppt online ka goen an ouni nei Verëffentlechung ugeschalt (oder nees ausgeschalt) ka ginn.","also":["Feature-Flags","Feature Flag","Feature Flags","Feature Toggle","Feature Toggles"]},{"id":"rollfwd","g":"change","word":"Roll Forward","text":"Eng schlecht Verëffentlechung flécken, andeems een séier eng nei, korrigéiert Versioun erausbréngt, amplaz op déi al zréckzegoen.","also":["Rolling Forward","Rolled Forward","Roll-forward"]},{"id":"canary","g":"change","word":"Canary Release","text":"Eng Ännerung fir d'éischt fir eng kleng Grupp online setzen, an eréischt fir jiddereen, wann et gutt ausgesäit. Benannt no de Kanarievillercher, déi d'Biergaarbechter als fréi Warnung mat ënner d'Äerd geholl hunn.","also":["Canary Releases","Canary"]},{"id":"bluegreen","g":"change","word":"Blue-Green-Deployment","text":"Zwou Kopië vum Live-System halen an d'Leit op eemol op déi nei ëmschalten, sou datt een direkt zréckschalte kann, wann et schifgeet.","also":["Blue-Green","Blue Green Deployment"]},{"id":"zerodown","g":"change","word":"Deployment ouni Ausfallzäit","text":"Eng nei Versioun online setzen, ouni datt de Service jee fir seng Notzer ophält.","also":["Zero Downtime","Zero-Downtime","ouni Ausfall"]},{"id":"chgenable","g":"change","word":"Change Enablement","text":"Hëllefen, datt Ännerunge gelingen: de Risiko ofweien, déi richteg Zoustëmmung kréien an e gudden Zäitpunkt eraussichen. Och Change Management genannt.","also":["Change Management","Ännerungsmanagement"]},{"id":"cab","g":"change","word":"Change Advisory Board (CAB)","text":"Eng Grupp, déi wichteg Ännerungen ukuckt a sech eens gëtt, ob a wéini se duerchgefouert ginn dierfen.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard-Ännerung","text":"Eng Ännerung mat gerengem Risiko, déi all Kéier op déiselwecht bewäerten Aart gemaach gëtt, dofir ass se am Viraus guttgeheescht.","also":["Standard-Ännerungen","Standard Change","Standard Changes"]},{"id":"normchange","g":"change","word":"Normal Ännerung","text":"Eng Ännerung, déi muss kontrolléiert a guttgeheescht ginn, ier se duerchgefouert gëtt.","also":["Normal Ännerungen","Normal Change","Normal Changes"]},{"id":"emergchange","g":"change","word":"Noutfall-Ännerung","text":"Eng Ännerung, déi direkt muss geschéien, fir e grousse Problem ze léisen oder ze verhënneren, mat enger méi séierer Zoustëmmung.","also":["Noutfall-Ännerungen","Emergency Change","Emergency Changes"]},{"id":"automation","g":"change","word":"Automatiséierung","text":"De Computer eng Aarbecht, déi ëmmer erëm kënnt, vu selwer maache loossen, sou datt se méi séier geet an all Kéier op déiselwecht Aart gemaach gëtt.","also":["Automation","automatiséiert"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktur","text":"D'Maschinnen, Netzwierker a Servicer, op deenen Software leeft.","also":["Infra","Infrastructure"]},{"id":"iac","g":"change","word":"Infrastructure as Code (IaC)","text":"Deng Serveren an Astellungen a Fichieren beschreiwen, déi beim Code bleiwen, sou datt se all Kéier genee gläich nei opgebaut kënne ginn.","also":["IaC","Infrastruktur als Code"]},{"id":"cloud","g":"change","word":"Cloud","text":"Computeren, Späicherplaz a Servicer vun engem grousse Fournisseur iwwert d'Internet lounen, amplaz d'Maschinne selwer ze besëtzen.","also":["d'Cloud","Cloud Computing"]},{"id":"provider","g":"change","word":"Cloud-Fournisseur","text":"Eng Firma, déi Rechenleeschtung iwwert d'Internet verlount, wéi Amazon Web Services (AWS), Microsoft Azure oder Google Cloud.","also":["Cloud-Fournisseuren","Cloud Provider","Cloud Providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Wou deng App oder Websäit lieft a leeft, sou datt d'Leit dru kommen, meeschtens vun enger Firma gelount.","also":["gehost"]},{"id":"domain","g":"change","word":"Domainnumm","text":"D'Webadress, déi d'Leit aginn, wéi example.com. Du lounss se Joer fir Joer, dofir muss se erneiert ginn.","also":["Domainnimm","Domain Name","Domain Names","Domain"]},{"id":"dns","g":"change","word":"DNS","text":"Kuerzform vun Domain Name System: d'Adressbuch vum Internet, dat en Numm wéi example.com an d'Adress vum richtege Computer ëmwandelt.","also":["Domain Name System"]},{"id":"container","g":"change","word":"Container","text":"E verseegelte Package mat enger App an allem, wat se brauch, sou datt se op all Computer d'selwecht leeft. Docker ass dat bekanntst Tool.","also":["Containeren","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuell Maschinn (VM)","text":"E virtuelle Computer, deen an engem richtege leeft, sou datt eng grouss Maschinn sech wéi vill verhale kann.","also":["VM","VMs","Virtual Machine","Virtual Machines","virtuell Maschinnen"]},{"id":"serverless","g":"change","word":"Serverless","text":"Code lafe loossen, ouni selwer iergendwéi Serveren ze bedreiwen: de Fournisseur léisst en lafen, wann et néideg ass, an du bezuels, wat s du benotzt hues."},{"id":"lb","g":"change","word":"Load Balancer","text":"Eppes, dat d'Besucher op e puer Servere verdeelt, sou datt keen eenzegen iwwerlaascht gëtt.","also":["Load Balancers","Laaschtverdeeler"]},{"id":"cache","g":"change","word":"Cache","text":"E praktesche Späicher mat rezenten Resultater, no bei der Hand gehalen, sou datt datselwecht net nach eng Kéier muss geholl oder ausgerechent ginn. En eidel ze maachen, kann Säite flécken, déi al ausgesinn.","also":["Caches","Caching","Cached","Zwëschespäicher"]},{"id":"cdn","g":"change","word":"Content Delivery Network (CDN)","text":"E weltwäite Set vu Serveren, déi Kopië vun denge Säiten a Biller no bei de Besucher halen, sou datt se séier lueden.","also":["CDN"]},{"id":"migration","g":"change","word":"Migratioun","text":"Daten oder Systemer vun engem aalen Opbau an en neien ëmzéien, oder suergfälteg änneren, wéi eng Datebank opgebaut ass.","also":["Migratiounen","Migration","Migrations","Datebankmigratioun"]},{"id":"service","g":"run","word":"Service","text":"Eppes, wat s du gebaut hues an op dat d'Leit sech verloossen, wéi eng Websäit oder eng App, a wat gefleegt gëtt, fir datt et weider funktionéiert. Kräiz „Dëst Projet ass e Service“ un a so, wat en ubitt, wien en notzt a wien Bereetschaft huet.","also":["Servicer"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Wéi vill vun der Zäit e Service funktionéiert, meeschtens als Prozentsaz. 99,9 % erlaben nach ëmmer ongeféier 43 Minutten Ausfall am Mount.","also":["Uptime-Prozentsaz","Uptime Percentage","Erreechbarkeet"]},{"id":"uptime","g":"run","word":"Verfügbarkeetskontroll","text":"Eng automatesch Kontroll, all puer Minutten, ob däi Service nach äntwert. Wann se e puer Mol hannereneen feelschléit, mécht AI-gile vu sech aus eng Zwëschefall-Kaart op.","also":["Uptime-Kontrollen","Uptime Checks"]},{"id":"statuspage","g":"run","word":"Statussäit","text":"Eng ëffentlech Säit, déi weist, ob e Service funktionéiert (gréng, orange oder rout), mat der leschter Neiegkeet, sou datt d'Leit, déi en notzen, do nokucke kënnen amplaz ze froen.","also":["Statussäiten","Status Page"]},{"id":"desk","g":"run","word":"Service-Schalter","text":"Do, wou d'Froen an d'Meldunge vun de Leit ukommen, déi däi Service benotzen. AI-gile sortéiert all eenzel als Ufro, Incident oder Iddi a seet et, wann et no eppes ausgesäit, dat schonn gemellt gouf.","also":["Service-Schalteren","Helpdesk","Service Desk"]},{"id":"svcrequest","g":"run","word":"Service-Ufro","text":"Een freet no eppes Normalem, wéi engem neie Kont oder e bësse Hëllef, amplaz ze mellen, datt eppes futti ass. Se waart, bis se drun ass; en Incident geet vir.","also":["Service-Ufroen","Ufro"]},{"id":"incident","g":"run","word":"Zwëschefall","text":"Eppes, wat fir d'Leit, déi et grad benotzen, futti ass oder net richteg funktionéiert, wéi wann d'Websäit aus oder ganz lues ass. Eng 🔥 Incident-Kaart kënnt an der Schlaang virun: et nees an de Gang ze kréien, geet vir.","also":["Zwëschefäll","Incident","Virfall"]},{"id":"major","g":"run","word":"Gréisse Virfall","text":"E grousse Zwëschefall: vill Leit si betraff, oder Suen oder Daten a Gefor. Ee Knäppchen setzt all Team drun (Schwarm), weckt deen, deen Bereetschaft huet, a freet all 30 Minutten no engem Statusupdate.","also":["grousse Zwëschefall","Major Incident"]},{"id":"oncall","g":"run","word":"Bereetschaft","text":"Deen ze sinn, deen äntwert, wann eppes futti geet, och an der Nuecht. All Service huet en Teammember mat Bereetschaft, deen als éischte fir seng Zwëschefäll geweckt gëtt.","also":["op Ruff","On call","On-call"]},{"id":"replyby","g":"run","word":"Äntwertzäit","text":"Wéi laang eng Kaart op eng éischt Äntwert waarde kann, zum Beispill eng Stonn fir e Zwëschefall. Duerno kritt se eng rout Auer, sou datt näischt roueg vergiess gëtt. Och Äntwertziel genannt.","also":["Äntwertzäiten","Äntwertziel","Response Target"]},{"id":"postmortem","g":"run","word":"Post-Mortem","text":"E kuerze Réckbléck no engem Zwëschefall: wat geschitt ass, wat gehollef huet a wat ee soll änneren, ouni engem d'Schold ze ginn. E Zwëschefall kann net ouni een zougemaach ginn.","also":["Post-mortem","Postmortem","Réckbléck nom Zwëschefall"]},{"id":"problem","g":"run","word":"Problem","text":"Déi verstoppten Ursaach hannert engem oder méi Zwëschefäll. Eng 🧩 Problem-Kaart gruppéiert Zwëschefäll, déi ëmmer erëm kommen, sou datt d'Ursaach fonnt a fir ëmmer behuewe gëtt.","also":["Problemer"],"noTip":1},{"id":"rootcause","g":"run","word":"Grondursaach","text":"De richtege Grond, firwat eppes futti gaangen ass, net just dat, wat s du schif goe gesinn hues. Behief d'Grondursaach, an de Zwëschefall kënnt net méi erëm.","also":["Grondursaachen","Root Cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"E Behëllef, fir datt alles weider leeft, bis déi richteg Léisung prett ass, wéi eppes nei starten, wann et hänke bleift. En gëtt op d'Problem-Kaart geschriwwen, sou datt keen en nach eng Kéier muss erausfannen.","also":["Behëllef","Workarounds"]},{"id":"knownerror","g":"run","word":"Bekannte Feeler","text":"E Problem, deem seng Ursaach een kennt, deen awer nach net behuewen ass, meeschtens mat enger opgeschriwwener Iwwergangsléisung. 🧩 Bekannt Feeler lëscht se op, sou datt jiddereen d'Iwwergangsléisung benotzt, amplaz nees ze sichen.","also":["bekannt Feeler","Known Error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Schrëtt-fir-Schrëtt-Instruktiounen, fir eng bekannt Zort Ierger ze behiewen, sou datt et all Kéier d'selwecht a séier gemaach gëtt. No engem grousse Zwëschefall kann d'Team der eent virschloen, an du gëss däin OK.","also":["Runbooks"]},{"id":"ci","g":"run","word":"Konfiguratiounselement","text":"Eng Saach, op där däi Service berout, wéi e Server, en Domain, en Zertifikat, e Schlëssel oder e Lieferant. 🗂️ Konfiguratiounselementer lëscht se pro Service op, sou datt s du gesäis, wat en Incident betrëfft a wat erneiert oder gesäichert muss ginn.","also":["Konfiguratiounselementer","Configuration Item","CI"]},{"id":"expiry","g":"run","word":"Oflafdatum","text":"Den Datum, un deem eppes ophält ze funktionéieren, ausser et gëtt erneiert, wéi de Sécherheetszertifikat vun enger Websäit oder hir Webadress. AI-gile passt op dës Datumen op a mécht 30 Deeg virdrun fir all eenzelt eng Kaart, fir et z'erneieren, sou datt näischt iwwerraschend ophält.","also":["Oflafdatumer","Oflaf","Oflafiwwerwaachung"]},{"id":"backup","g":"run","word":"Sécherung","text":"Eng gespäichert Kopie vun dengen Daten vu virdrun, op déi s du zréckgräife kanns, wann eppes verluer geet oder beschiedegt gëtt. AI-gile mécht all Dag eng Sécherung vun denge Bierder.","also":["Sécherungen","Backup"]},{"id":"restore","g":"run","word":"Erëmhierstellen","text":"Daten aus enger Sécherung zréckspillen. Eng Sécherung zielt eréischt richteg, wann s du weess, datt een se erëmhierstelle kann, also lount et sech, dat ab an zou ze probéieren.","also":["erëmhiergestallt","Restore"]},{"id":"svcreview","g":"run","word":"Service-Review","text":"E Réckbléck op ee Mount vun engem Service: opgemaachen a gefléckten Incidenter, wéi séier d'Leit eng Äntwert kruten, Verfügbarkeet a verbrauchten Tokens. De Monatleche Review weist dat fir all Service.","also":["Service-Reviewen","Monatleche Review","monatleche Review"]},{"id":"accessreview","g":"run","word":"Zougangsiwwerpréiwung","text":"All 90 Deeg kontrolléieren, wien nach eran däerf: Share-Linken, Rolle vu Frënn a gespäichert Passwierder a Schlësselen. Du behäls oder läschs all eenzelt, sou datt keen ale Zougang hänke bleift.","also":["Zougangsiwwerpréiwungen","Access Review"]},{"id":"improvements","g":"run","word":"Verbesserungslëscht","text":"Alles, wat d'Team decidéiert huet besser ze maachen, op enger Plaz: Retro-Virschléi, Review-Aktiounen a Problem-Léisungen, all mat sengem Status. Du fënns se ënner 📈 Verbesserungen.","also":["Verbesserungslëschten","Verbesserungen"]},{"id":"tokencap","g":"run","word":"Token-Limit","text":"Eng monatlech Limit fir d'Tokens, déi d'Agente vun engem Service benotze kënnen. Bei 80% kriss du eng Warnung; bei 100% waart hir Aarbecht am Hannergrond bis den nächste Mount oder bis s du d'Limit erhéichs.","also":["Token-Limitten","monatlech Token-Limit"]},{"id":"svcmgmt","g":"run","word":"Service Management","text":"Alles, wat dozou gehéiert, e Service nëtzlech an am Gang ze halen fir d'Leit, déi sech drop verloossen, Dag fir Dag.","also":["Servicemanagement","e Service verwalten"]},{"id":"itil","g":"run","word":"ITIL","text":"E vill benotzte Leetfuedem fir gutt Servicemanagement, deen Themen ewéi Stéierungen, Problemer an Ännerungen ofdeckt. Den Numm stoung fréier fir IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-Service-Management (ITSM)","text":"Technologie als Service fir Leit bedreiwen, mat kloere Weeër, fir Ufroen, Stéierungen, Ännerungen a Verbesserungen ze behandelen.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed Service","text":"E Service, deen een anere fir dech bedreift a betreit, no engem Accord doriwwer, wéi gutt e funktionéiere muss.","also":["Managed Services"]},{"id":"svcowner","g":"run","word":"Service-Owner","text":"D'Persoun, déi fir e Service als Ganzt d'Verantwortung dréit: wéi gutt e funktionéiert, wat e kascht a wéi e besser gëtt.","also":["Service-Owner","Service Owner","Service Owners"]},{"id":"sla","g":"run","word":"Service Level Agreement (SLA)","text":"E schrëftlecht Verspriechen un d'Clienten doriwwer, wéi gutt e Service wäert funktionéieren, wéi „99,9 % vun der Zäit erreechbar“ oder „bannent enger Stonn beäntwert“, dacks mat Geld zeréck, wann et net agehale gëtt.","also":["SLA","SLAs","Service Level Agreement"]},{"id":"slo","g":"run","word":"Service Level Objective (SLO)","text":"Dat eegent Zil vum Team, wéi gutt e Service iwwer eng Period soll funktionéieren, meeschtens e bësse méi streng wéi de SLA, fir sécher ze goen.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service Level Indicator (SLI)","text":"Déi tatsächlech Messung, déi s du mat engem Zil vergläichs, wéi den Undeel u Besicher, bei deenen d'Säit gutt gelueden huet.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Verfügbarkeet","text":"Ob d'Leit e Service benotze kënnen, wa se e brauchen, dacks als Uptime gemooss.","also":["Héich Verfügbarkeet","Availability","High Availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Zäit, wou e Service net funktionéiert oder ausgeschalt ass, geplangt oder net.","also":["Down Time","Ausfallzäit"]},{"id":"errorbudget","g":"run","word":"Error Budget","text":"Dat klengt Quantum u Feeler, dat däi Zouverlässegkeetszil erlaabt. Soulaang nach eppes iwwreg ass, kanns du bei Ännerunge Risiken agoen; ass et opgebraucht, gees du et méi lues un.","also":["Error Budgets","Feeler-Budget"]},{"id":"outage","g":"run","word":"Ausfall","text":"Eng Zäit, wou e Service fir seng Notzer aus oder schwéier futti ass.","also":["Ausfäll","Outage","Outages"]},{"id":"degraded","g":"run","word":"Ageschränkt","text":"Et funktionéiert, awer schlecht: lues, oder mat e puer Deeler, déi net goen.","also":["Ageschränkte Service","Degraded","Degraded Service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"E Service dauernd automatesch beobachten, sou datt Problemer opfalen, am beschten, ier d'Notzer eppes mierken.","also":["Iwwerwaachung"]},{"id":"observability","g":"run","word":"Observability","text":"Wéi gutt s du vu baussen erkenne kanns, wat bannen an engem System lass ass, mat senge Logs, Zuelen an Traces.","also":["o11y","Observabilitéit"]},{"id":"log","g":"run","word":"Log","text":"E lafent Dagbuch, dat e Programm iwwer dat féiert, wat e mécht; domat fënnt een eraus, wat schifgaangen ass.","also":["Logs","Logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Eng Opzeechnung, wéi eng eenzel Ufro duerch déi verschidden Deeler vun engem System reest, Schrëtt fir Schrëtt, déi weist, wou se lues gouf.","also":["Traces","Tracing"]},{"id":"latency","g":"run","word":"Latenz","text":"Wéi laang eppes brauch, fir z'äntwerten, wéi d'Waarden tëscht dem Klick an dem Erschéngen vun der Säit.","also":["Latency"]},{"id":"alert","g":"run","word":"Alarm","text":"En automatesche Message, datt eppes Opmierksamkeet brauch, wéi wann d'Websäit net äntwert.","also":["Alarmer","Alert","Alerts","Alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alarm-Midegkeet","text":"Wann et esou vill Alarmer gëtt, datt d'Leit ufänken, se z'ignoréieren, och déi wichteg.","also":["Alert Fatigue","Alarm Fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"E Bildschierm, deen déi wichtegst Zuelen a Statuser op ee Bléck weist.","also":["Dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Déi Persoun, déi Bereetschaft huet, dréngend uruffen oder erwächen, wéinst engem Problem.","also":["Paged","Alarméieren"]},{"id":"escalation","g":"run","word":"Eskalatioun","text":"Een derbäihuelen, dee méi Kompetenz oder Autoritéit huet, wann eng Saach um aktuellen Niveau net oder net séier genuch ka geléist ginn.","also":["Eskaléieren","Eskaléiert","Escalation","Escalate","Escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Erakommend Problemer séier no Dringlechkeet a Wichtegkeet zortéieren, sou datt dat Schlëmmst als éischt drun kënnt.","also":["Triaged","Triagéieren"]},{"id":"impact","g":"run","word":"Impakt","text":"Wéi vill eppes d'Leit beaflosst: wéi vill, a wéi schlëmm.","noTip":1},{"id":"urgency","g":"run","word":"Dringlechkeet","text":"Wéi séier eppes muss behandelt ginn. Impakt an Dringlechkeet zesumme bestëmmen d'Prioritéit.","noTip":1},{"id":"plevels","g":"run","word":"Prioritéitsniveauen (P1, P2…)","text":"Etiketten, déi weisen, wéi dréngend e Problem ass. P1 ass dee schlëmmsten a muss direkt ugepaakt ginn.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket-Schlaang","text":"D'Lëscht vun Ufroen a Stéierungen, déi doropper waarden, opgeholl ze ginn.","also":["Ticket-Schlaangen","Ticket Queue","Ticket Queues"]},{"id":"tiers","g":"run","word":"First Line a Second Line (éischten an zweeten Niveau)","text":"Niveaue vum Support: den éischten hëlt den Uruff un a léist einfach Saachen; den zweeten huet méi déif Kompetenze fir déi méi schwéier. Och Tier 1 an Tier 2 genannt.","also":["éischten Niveau","zweeten Niveau","First-Line Support","Tier 1","Tier 2"]},{"id":"ic","g":"run","word":"Incident Commander","text":"Déi eng Persoun, déi d'Reaktioun op eng Stéierung leet, sou datt jiddereen weess, wien entscheet a wien wat mécht.","also":["Incident Commanders"]},{"id":"responsetime","g":"run","word":"Reaktiounszäit","text":"Wéi laang et dauert, bis een eng Ufro oder Stéierung fir d'éischt opgeholl huet.","also":["Reaktiounszäiten","Response Time","Response Times"]},{"id":"resolution","g":"run","word":"Léisungszäit","text":"Wéi laang et dauert, eng Ufro oder Stéierung ganz ze léisen, vun der Meldung bis zur Reparatur.","also":["Léisungszäiten","Resolution Time","Resolution Times","Time to Resolve"]},{"id":"mttr","g":"run","word":"Mean Time to Recover (MTTR)","text":"Am Duerchschnëtt, wéi laang et dauert, e Service nees an de Gang ze kréien, nodeems e futti gaangen ass. MTTR ka liicht Ënnerschiddleches bedeiten, also so, wat s du moss.","also":["MTTR","Mean Time to Restore"]},{"id":"mtbf","g":"run","word":"Mean Time Between Failures (MTBF)","text":"Am Duerchschnëtt, wéi laang e Service leeft, ier eppes futti geet.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration Management Database (CMDB)","text":"D'Lëscht vun all denge Konfiguratiounselementer a wéi se matenee verbonne sinn, sou datt s du gesäis, wat vu wat ofhänkt.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset (Wäertsaach)","text":"Alles vu Wäert, wat s du besëtz oder bezuels, fir de Service ze bedreiwen, wéi e Laptop, eng Software-Lizenz oder eng Domain.","also":["Assets","Wäertsaachen"],"noTip":1},{"id":"capplan","g":"run","word":"Kapazitéitsplanung","text":"Suergen, datt et genuch Rechenleeschtung, Späicherplaz a Leit fir dat gëtt, wat kënnt.","also":["Kapazitéitsplang","Capacity Planning","Capacity Plan"]},{"id":"scaling","g":"run","word":"Skaléieren","text":"Mat méi Notzer eens ginn, andeems eng Maschinn méi Leeschtung kritt (Scale up) oder méi Maschinnen derbäikommen (Scale out).","also":["Scaling","Scale up","Scale out","Scaling up","Scaling out","eropskaléieren"]},{"id":"bcp","g":"run","word":"Betribskontinuitéit","text":"Pläng, fir déi wichteg Saachen um Lafen ze halen, wann eppes Grousses schifgeet, wéi wann ee säi Büro, e wichtege Liwwerant oder d'Computere verléiert.","also":["Business Continuity","Business Continuity Plan","Betribskontinuitéitsplang"]},{"id":"dr","g":"run","word":"Disaster Recovery (DR)","text":"De Plang an d'Tools, fir e Service erëm zum Lafen ze bréngen, nodeems eppes Eescht geschitt ass, wéi wann e ganzt Rechenzentrum ausfält.","also":["Disaster Recovery","Erëmhierstellung no enger Katastroph"]},{"id":"rto","g":"run","word":"Recovery Time Objective (RTO)","text":"Déi längst Zäit, déi e Service no enger Katastroph ausfale dierf, ier e nees muss funktionéieren.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery Point Objective (RPO)","text":"Wéi vill rezent Daten s du dir kanns leeschten ze verléieren, an der Zäit gemooss. E RPO vun enger Stonn heescht Backuppen op d'mannst all Stonn.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redondanz","text":"Reserve prett hunn, wéi en zweete Server, sou datt en eenzegen Ausfall de Service net stoppt.","also":["Redundanz","Redundancy","redondant"]},{"id":"failover","g":"run","word":"Failover","text":"Vu selwer op e Reservesystem ëmschalten, wann deen normale System ausfält.","also":["Fail over","Ëmschalten bei Ausfall"]},{"id":"spof","g":"run","word":"Single Point of Failure","text":"Een Deel, deen alles mat sech erofzitt, wann e futti geet, well et keng Reserve gëtt.","also":["Single Points of Failure","SPOF","eenzege Schwaachpunkt"]},{"id":"maintwin","g":"run","word":"Maintenance-Fënster (Ënnerhaltszäit)","text":"Eng geplangten Zäit, wou e Service wéinst Ënnerhaltsaarbechten ënnerbrach oder lues ka sinn, an déi den Notzer am Viraus ugekënnegt gëtt.","also":["Maintenance Window","Maintenance Windows","Planned Maintenance","Ënnerhaltsfënster","geplangten Ënnerhalt"]},{"id":"handover","g":"run","word":"Iwwergab","text":"Aarbecht, Wëssen a Verantwortung un eng aner Persoun oder en anert Team weiderginn, sou datt näischt verluer geet.","also":["Iwwergaben","Handover","Handovers"]},{"id":"kb","g":"run","word":"Wëssensdatebank","text":"Eng Sammlung vun Hëllefsartikelen an Äntwerten, fir d'Notzer a fir d'Team.","also":["Wëssensdatebanken","Knowledge Base","Knowledge Bases"]},{"id":"csat","g":"run","word":"Clientszefriddenheet (CSAT)","text":"E Score vun den Notzer, deen seet, wéi zefridde se waren, dacks gefrot, nodeems eng Ufro zougemaach gouf.","also":["CSAT","Customer Satisfaction","Zefriddenheet"]},{"id":"supplier","g":"run","word":"Liwwerant","text":"Eng extern Firma, op déi s du dech verléiss, wéi däi Hosting-Fournisseur. Och Vendor oder Drëtt Partei genannt.","also":["Liwweranten","Supplier","Suppliers","Vendor","Vendors","Drëtt Partei","Third Party"],"noTip":1},{"id":"retire","g":"run","word":"Service-Ofschaffung","text":"E Service definitiv a sécher ausschalten: seng Notzer informéieren, sech ëm seng Daten an Zougäng këmmeren a seng Käschte stoppen.","also":["E Service ofschaffen","Retiring a Service"]},{"id":"eol","g":"run","word":"End of Life (EOL)","text":"Wann e Produkt vu sengem Hiersteller keng Updates oder Ënnerstëtzung méi kritt, dofir soll et ersat ginn.","also":["EOL","End-of-Life"]},{"id":"cybersec","g":"sec","word":"Cybersécherheet","text":"Systemer an Daten dovir schützen, datt een do abrécht oder datt se geklaut oder beschiedegt ginn.","also":["Cyber Security","Cybersecurity"]},{"id":"authn","g":"sec","word":"Authentifizéierung","text":"Kontrolléieren, wien een ass, meeschtens mat engem Passwuert oder engem Code. Dacks zu authn ofgekierzt.","also":["Authn","Authentication"]},{"id":"authz","g":"sec","word":"Autorisatioun","text":"Kontrolléieren, wat een dierf maachen, wann ee weess, wien et ass. Dacks zu authz ofgekierzt.","also":["Authz","Authorisation","Authorization"]},{"id":"mfa","g":"sec","word":"Multi-Faktor-Authentifizéierung (MFA)","text":"Mat zwee oder méi Beweiser aloggen, wéi e Passwuert plus e Code um Telefon. Och Zwee-Faktor (2FA) genannt.","also":["MFA","2FA","Zwee-Faktor","Zwee-Faktor-Authentifizéierung","Two-Factor","Two-Factor Authentication"]},{"id":"sso","g":"sec","word":"Single Sign-on (SSO)","text":"Eemol aloggen, fir a ville Systemer eranzekommen, wéi wann s du iwwerall däi Aarbechtskont benotz.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Passwuertmanager","text":"Eng App, déi staark Passwierder erstellt a se fir dech behält.","also":["Passwuertmanageren","Password Manager","Password Managers"]},{"id":"secret","g":"sec","word":"Secret (Geheimnis)","text":"E Passwuert, e Schlëssel oder en anere privaten Code, deen e Programm benotzt, fir an eppes eranzekommen. E däerf ni gedeelt oder an de Code geschriwwe ginn.","also":["Secrets","Geheimnisser"],"noTip":1},{"id":"apikey","g":"sec","word":"API-Schlëssel","text":"E geheime Code, deen engem Programm erlaabt, d'API vun engem anere Service ze benotzen, an deen weist, wien en notzt (a wien dofir bezilt).","also":["API-Schlësselen","API Key","API Keys"]},{"id":"accesstoken","g":"sec","word":"Access-Token","text":"Eng temporär Zougangskaart, déi beweist, datt e Programm eran dierf, sou datt e net all Kéier däi Passwuert brauch. Net datselwecht wéi e KI-Token.","also":["Access-Tokens","Access Token","Access Tokens"]},{"id":"encryption","g":"sec","word":"Verschlësselung","text":"Informatiounen duerchenee bréngen, sou datt nëmmen een mam richtege Schlëssel se liese kann.","also":["verschlësselt","verschlësselen","Encryption","Encrypted","Encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Déi sécher Manéier, wéi Websäiten ënnerwee sinn, um Schlass am Browser z'erkennen, sou datt keen dertëscht se liesen oder ännere kann."},{"id":"cert","g":"sec","word":"SSL/TLS-Zertifikat","text":"En digitalen Ausweis, deen enger Websäit erlaabt ze beweisen, wien se ass, an HTTPS ze benotzen. E leeft of, dofir muss en erneiert ginn.","also":["TLS-Zertifikat","SSL-Zertifikat","Zertifikat","Zertifikater","TLS Certificate","SSL Certificate","Certificate","Certificates"]},{"id":"permissions","g":"sec","word":"Rechter","text":"D'Reegelen, wien wat gesinn oder ännere dierf.","also":["Recht","Permissions","Permission","Autorisatiounen"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least Privilege (sou wéineg Rechter wéi néideg)","text":"All Persoun oder all Programm nëmmen den Zougang ginn, deen se wierklech brauchen, an nëmmen esou laang, wéi se e brauchen.","also":["Least Privilege","Principle of Least Privilege","Prinzip vun de mannste Rechter"]},{"id":"rbac","g":"sec","word":"Rollebaséierten Zougang (RBAC)","text":"Zougang no Roll ginn, wéi Leser oder Editeur, amplaz Persoun fir Persoun.","also":["RBAC","Role-Based Access Control","Role-Based Access","Rollenzougang"]},{"id":"vuln","g":"sec","word":"Schwaachstell","text":"E schwaache Punkt, deen een ausnotze kann, fir anzebriechen oder Schued unzeriichten.","also":["Schwaachstellen","Vulnerability","Vulnerabilities","Sécherheetslück"]},{"id":"zeroday","g":"sec","word":"Zero-Day","text":"Eng Schwaachstell, déi Ugräifer kennen, ier d'Hiersteller iwwerhaapt Zäit haten, se ze behiewen.","also":["Zero-Days","Zero Day"]},{"id":"malware","g":"sec","word":"Malware","text":"Schiedlech Software, wéi Viren, gemaach fir ze beschiedegen, ze spionéieren oder ze klauen.","also":["schiedlech Software"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware, déi deng Fichiere spaart a Geld verlaangt, fir se nees opzemaachen. Gutt Backuppe sinn déi bescht Verdeedegung.","also":["Ransomware-Attack","Ransomware Attack","Erpressungssoftware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Falsch Noriichten, déi probéieren, dech eranzeleeën, fir u Passwierder oder Geld ze kommen, oder dech eppes Schiedleches opmaachen ze loossen.","also":["Phishing-E-Mail","Phishing-E-Mailen","Phishing Email","Phishing Emails"]},{"id":"socialeng","g":"sec","word":"Social Engineering","text":"Leit eraleeën, amplaz Computeren, fir Zougang ze kréien, wéi mat engem falschen Uruff vum „IT-Support“."},{"id":"firewall","g":"sec","word":"Firewall","text":"E Wiechter, deen entscheet, wat fir Netzwierkverkéier eran- oder erausgoe dierf.","also":["Firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kuerzform vu Virtual Private Network: eng privat, verschlësselt Verbindung iwwert d'Internet, dacks benotzt, fir sécher op Aarbechtssystemer ze kommen.","also":["Virtual Private Network","virtuellt privat Netzwierk"]},{"id":"ddos","g":"sec","word":"Denial of Service (DoS, DDoS)","text":"E Service mat sou vill falschem Verkéier iwwerschwemmen, datt richteg Leit en net méi benotze kënnen. DDoS heescht, et kënnt vu villen Computeren op eemol.","also":["DoS","DDoS","Denial of Service","DDoS Attack","DDoS-Attack"]},{"id":"pentest","g":"sec","word":"Penetratiounstest (Pen-Test)","text":"Frëndlech Experten engagéieren, déi probéieren anzebriechen, sou datt Schwaachstelle fonnt ginn, ier richteg Ugräifer se fannen.","also":["Pen-Test","Pen Test","Pen Testing","Penetration Testing","Pentest"]},{"id":"audit","g":"sec","word":"Sécherheetsaudit","text":"Eng suergfälteg Kontroll, wéi gutt eppes geschützt ass, mat enger Lëscht vu gudder Praxis als Moossstaf.","also":["Sécherheetsauditen","Security Audit","Security Audits"]},{"id":"threatmodel","g":"sec","word":"Threat Modelling","text":"Duerchdenken, wien eppes kéint attackéieren, wéi, a wat s du géifs maachen, fir se ze stoppen.","also":["Threat Model","Threat Modeling","Bedrohungsmodell","Gefoorenanalys"]},{"id":"breach","g":"sec","word":"Dateleck","text":"Wann privat Informatiounen u Leit erauskommen, déi se net kréie sollten, oder ouni Erlaabnis verluer goen oder geännert ginn.","also":["Datelecker","Data Breach","Data Breaches"]},{"id":"pii","g":"sec","word":"Perséinlech Daten","text":"All Informatioun iwwer eng Persoun, déi sech identifizéiere léisst, wéi en Numm, eng E-Mail-Adress oder e Standuert. Och PII genannt.","also":["PII","Personally Identifiable Information"]},{"id":"gdpr","g":"sec","word":"RGPD (GDPR)","text":"Dat europäescht Gesetz iwwer perséinlech Daten (Groussbritannien huet seng eege Versioun): sammel nëmmen, wat s du brauchs, hal se sécher, a loss d'Leit hir eegen Daten gesinn oder läschen.","also":["GDPR","DSGVO","RGPD","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Dateschutz","text":"Mat perséinlechen Daten richteg a gesetzlech ëmgoen.","also":["Dateschutzgesetz","Data Protection","Data Protection Law"]},{"id":"privacypolicy","g":"sec","word":"Dateschutzerklärung","text":"Eng ëffentlech Säit, déi seet, wéi eng perséinlech Daten s du sammels, firwat, a wat s du domat mechs.","also":["Dateschutzerklärungen","Privacy Policy","Privacy Statement","Privacy Notice"]},{"id":"consent","g":"sec","word":"Zoustëmmung","text":"E kloert, fräit Jo vun enger Persoun dozou, datt hir Daten op eng bestëmmt Aart benotzt ginn. Si kann et all Moment zréckzéien.","also":["Consent","Opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"E klenge Fichier, deen eng Websäit an dengem Browser späichert, fir sech u Saachen z'erënneren, zum Beispill datt s du ageloggt bass. Fir e puer brauch et fir d'éischt deng Zoustëmmung.","also":["Cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Datesparsamkeet","text":"Nëmmen déi perséinlech Daten sammelen an halen, déi s du fir d'Aarbecht wierklech brauchs.","also":["Dateminimiséierung","Data Minimisation","Data Minimization"]},{"id":"retention","g":"sec","word":"Datespäicherdauer","text":"Wéi laang Daten opbewaart ginn, ier se geläscht ginn. Se net méi laang ze halen wéi néideg, ass méi sécher an dacks gesetzlech virgeschriwwen.","also":["Späicherdauer","Data Retention","Retention Period"]},{"id":"anon","g":"sec","word":"Anonymiséierung","text":"Daten esou änneren, datt een doraus realistesch keen eenzege Mënsch méi identifizéiere kann.","also":["anonymiséiert","Anonymisation","Anonymised","Anonymization","anonym Daten"]},{"id":"pseudo","g":"sec","word":"Pseudonymiséierung","text":"Nimm an aner Detailer duerch Coden ersetzen, mat engem Schlëssel, deen apart gehale gëtt, fir se nees zesummenzebréngen. Et sinn awer ëmmer nach perséinlech Daten.","also":["pseudonymiséiert","Pseudonymisation","Pseudonymised","Pseudonymization"]},{"id":"dpa","g":"sec","word":"Veraarbechtungsvertrag (DPA)","text":"E Kontrakt, deen seet, wéi e Liwwerant perséinlech Daten an dengem Numm behandele dierf.","also":["DPA","Data Processing Agreement"]},{"id":"dpia","g":"sec","word":"Dateschutz-Folgenofschätzung (DPIA)","text":"E suergfältege Bléck virum Ufank drop, wéi e Plang, perséinlech Daten ze benotzen, d'Leit beaflosse kéint, a wéi een d'Risike senke kann.","also":["DPIA","Data Protection Impact Assessment","Folgenofschätzung"]},{"id":"auditlog","g":"sec","word":"Audit-Log","text":"Eng Opzeechnung, wien wat a wéini gemaach huet, sou datt Aktioune méi spéit kënne kontrolléiert ginn.","also":["Audit-Logs","Audit Log","Audit Logs","Audit Trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"D'Gesetzer, Reegelen a Standarden, déi fir dech gëllen, anhalen, a weise kënnen, datt s du et méchs.","also":["compliant","konform"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"E bekannten internationale Standard fir d'Informatiounssécherheet ze managen. Firme kënne sech dofir zertifiéiere loossen.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"En US-Rapport, vun externen Auditeure kontrolléiert, dee weist, datt eng Firma richteg mat de Clientsdaten ëmgeet.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Eng KI, déi vu selwer un enger Aufgab schafft: de Code liest, Ännerunge mécht, Kontrolle lafe léisst a Bescheed gëtt. Hir Aarbecht gëtt awer nach ëmmer kontrolléiert.","also":["Agenten","Agents"]},{"id":"token","g":"ai","word":"Token","text":"Déi kleng Stécker Text, déi eng KI liest a schreift, all eent ongeféier dräi Véirel vun engem Wuert. D'KI-Notzung gëtt a Tokens gezielt, dofir loosse manner Tokens méi vun dengem Plang iwwreg.","also":["Tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"E klenge Kommando, dee vu selwer zu engem bestëmmte Moment leeft, zum Beispill wann eng KI-Sessioun ufänkt, sou datt d'Team deng Kommentarer héiert.","also":["Hooks"]},{"id":"ai","g":"ai","word":"Kënschtlech Intelligenz (KI)","text":"Computersystemer, déi Saache maachen, fir déi mir normalerweis mengen, et bräicht e Mënsch, wéi schreiwen, Froen beäntwerten oder Biller erkennen.","also":["KI","AI","Artificial Intelligence","kënschtlech Intelligenz"],"noTip":1},{"id":"ml","g":"ai","word":"Machine Learning (ML)","text":"Eng Manéier, Computere Muster aus ville Beispiller léieren ze loossen, amplaz hinne genau Reegelen ze ginn.","also":["Machine Learning","maschinellt Léieren"]},{"id":"model","g":"ai","word":"Modell","text":"D'trainéiert „Gehir“ vun engem KI-System, dat entsteet, andeems et aus enorm ville Beispiller léiert. Modeller ënnerscheede sech a Kënnen, Tempo a Präis.","also":["Modeller","Model","Models","KI-Modell"],"noTip":1},{"id":"llm","g":"ai","word":"Grousst Sproochmodell (LLM)","text":"E KI-Modell, deen op enorm vill Text trainéiert gouf, sou datt e Sprooch liesen a schreiwe kann.","also":["LLM","LLMs","Large Language Model","Sproochmodell"]},{"id":"genai","g":"ai","word":"Generativ KI","text":"KI, déi nei Saache schaaft, wéi Text, Biller oder Code, amplaz se just ze zortéieren oder z'erkennen.","also":["GenAI","Generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"E Programm, mat deem s du an der Alldagssprooch kommunizéiers, andeems s du tipps oder schwätz.","also":["Chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Dat, wat s du enger KI gëss: deng Fro oder Uweisungen, plus alles, wat s du hir matgëss. Méi kloer Prompts kréie meeschtens besser Äntwerten.","also":["Prompts"]},{"id":"prompteng","g":"ai","word":"Prompt Engineering","text":"D'Konscht, Prompts ze schreiwen, déi zouverlässeg, nëtzlech Resultater bréngen."},{"id":"sysprompt","g":"ai","word":"System-Prompt","text":"Hannergrond-Uweisungen, déi eng KI kritt, ier d'Gespréich ufänkt, a déi hir Roll a Reegele festleeën. Si zielen méi wéi dat, wat s du tipps.","also":["System-Prompts","System Prompt","System Prompts","System Instruction","System Instructions","Systemuweisung"]},{"id":"context","g":"ai","word":"Kontext","text":"Alles, wat d'KI gesäit, wärend se schafft: d'Uweisungen, deng Messagen, Fichieren, déi se gelies huet, a fréier Äntwerten.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontextfënster","text":"Wéi vill eng KI op eemol am Kapp ka behalen, a Tokens gemooss. Doriwwer gi méi al Deeler fale gelooss oder zesummegefaasst.","also":["Kontextfënsteren","Context Window","Context Windows"]},{"id":"session","g":"ai","word":"Sessioun","text":"En Aarbechtsgespréich mat enger KI, vum Ufank bis zum Enn. Eng nei Sessioun fänkt mat engem eidele Gedächtnis un.","also":["Sessiounen","Session","Sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Gedächtnis","text":"Notizen, déi eng KI tëscht Sessiounen hält, sou datt se sech un deng Virléiften a fréier Entscheedungen erënnert.","noTip":1},{"id":"hallucination","g":"ai","word":"Halluzinatioun","text":"Wann eng KI eppes seet, wat sech sécher unhéiert, awer erfonnt oder falsch ass. Kontrolléier wichteg Fakten.","also":["Halluzinatiounen","Hallucination","Hallucinations","Hallucinate","Hallucinates","halluzinéieren"]},{"id":"training","g":"ai","word":"Training","text":"E Modell trainéieren, andeems een him enorm vill Beispiller weist, ier iergendeen en notzt.","also":["trainéieren","Trained","trainéiert"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trainingsdaten","text":"D'Beispiller, aus deenen e Modell geléiert huet. Säi Wëssen hält beim Datum op, wou déi Daten gesammelt goufen.","also":["Training Data","Training Set","Trainingsset"]},{"id":"cutoff","g":"ai","word":"Wëssensgrenz","text":"Den Datum, wou dat agebaut Wëssen vun enger KI ophält. Si weess näischt vu spéideren Saachen, ausser si kuckt se no.","also":["Knowledge Cutoff","Training Cutoff","Cutoff-Datum"]},{"id":"finetune","g":"ai","word":"Fine-Tuning","text":"Zousätzlecht Training vun engem bestehende Modell op deng eege Beispiller, fir en an enger bestëmmter Aufgab besser ze maachen.","also":["Fine-Tune","Fine-Tuned","Fine Tuning","Feinjustéierung"]},{"id":"inference","g":"ai","word":"Inferenz","text":"E KI-Modell, dee wierklech benotzt gëtt, fir eppes ze beäntwerten, am Géigesaz zum Trainéieren.","also":["Inference","Model Inference"]},{"id":"tooluse","g":"ai","word":"Tool-Notzung","text":"Eng KI, déi Saache maache kann, net just schwätzen: Kommandoen ausféieren, Fichiere liesen oder am Web sichen, mat Tools, déi d'App hir gëtt.","also":["Tool Use","Tool Calling","Tool Call","Tool Calls","Tool-Opruff"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Eng Helfer-KI, där eng Haapt-KI eng méi kleng Aarbecht iwwerreecht an d'Resultat dovunner zréckkritt.","also":["Subagenten","Subagents","Sub-Agent"]},{"id":"multiagent","g":"ai","word":"Multi-Agent","text":"Méi KIen, déi zesummen un engem Stéck Aarbecht schaffen, all eng mat hirem eegenen Deel, wéi e klengt Team.","also":["Multi-Agent-System","Multi-Agent System"]},{"id":"autonomy","g":"ai","word":"Autonomie","text":"Wéi vill eng KI vu selwer dierf maachen, ier se e Mënsch muss froen.","also":["Autonomy","autonom","Autonomous"]},{"id":"hitl","g":"ai","word":"Human in the Loop","text":"E Mënsch derbäi halen, deen un de wichtege Punkte kontrolléiert oder guttheescht, wat d'KI mécht. Bei AI-gile bass dat du.","also":["Human-in-the-Loop","HITL","Mënsch an der Schleef"]},{"id":"guardrails","g":"ai","word":"Guardrails (Sécherheetsbarrièren)","text":"Limiten a Kontrollen, déi d'Aktioune vun enger KI sécher halen, wéi eng Zoustëmmung, ier eppes online geet. Si senken de Risiko vu Feeler, schléissen se awer net aus.","also":["Guardrail","Sécherheetsbarrière"]},{"id":"rag","g":"ai","word":"Retrieval-Augmented Generation (RAG)","text":"Eng KI an dengen eegenen Dokumenter eppes nokucke loossen, ier se äntwert, sou datt hir Äntwerten op denge Fakte baséieren.","also":["RAG","Retrieval Augmented Generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Text an eng Lëscht vun Zuelen ëmwandelen, déi seng Bedeitung festhält, sou datt e Computer Saache fënnt, déi ähnlech bedeiten.","also":["Embeddings"]},{"id":"vectordb","g":"ai","word":"Vektordatebank","text":"Eng Datebank, gebaut fir dës Lëschte vun Zuelen (Embeddings) ze duerchsichen, fir Material mat ähnlecher Bedeitung ze fannen.","also":["Vektordatebanken","Vector Database","Vector Databases","Vector Store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Eng gemeinsam Manéier, Tools an Datequellen an KI-Appen anzestiechen, sou datt eng KI se notze kann.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatur","text":"Eng Astellung dofir, wéi experimentéierfreedeg d'Äntwerte vun enger KI sinn. Niddreg gëtt méi stabil Äntwerten, déi een éischter virausgesäit; héich gëtt méi ofwiesslungsräich. Kee vun deenen zwee mécht se ëmmer richteg.","also":["Temperature","Model Temperature","Modelltemperatur"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Fäeg, mat méi wéi enger Zort Informatioun ze schaffen, wéi Text, Biller a Toun.","also":["Multi-modal"]},{"id":"evals","g":"ai","word":"Evaluatioun (Eval)","text":"E geplangten Test, wéi gutt eng KI bei ausgewielte Beispiller ofschneit, sou datt s du Modeller oder Prompts vergläiche kanns.","also":["Eval","Evals","Evaluatiounen"]},{"id":"bias","g":"ai","word":"Bias (Viruerteel)","text":"Wann eng KI (oder e Mënsch) ongerecht op eng Säit tendéiert, dacks wéinst deem, vun deem se geléiert huet.","also":["Biased","Viruerteel","Viruerteeler"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsabel KI","text":"KI fair, sécher an éierlech benotzen, wou Mënschen nach ëmmer fir d'Resultater responsabel sinn.","also":["Ethesch KI","Responsible AI","Ethical AI"]},{"id":"injection","g":"ai","word":"Prompt Injection","text":"En Trick, wou verstoppt Uweisungen an enger Websäit oder engem Fichier probéieren, eng KI dozou ze bréngen, eppes ze maachen, wat hire Benotzer net gefrot huet.","also":["Prompt Injections"]},{"id":"ratelimit","g":"ai","word":"Rate Limit","text":"E Limit, wéi vill Ufroen s du an enger festgeluechter Zäit un e Service schécken däerfs. Gees du driwwer, muss s du waarden.","also":["Rate Limits","Rate Limited","Ufroe-Limit"]},{"id":"usagelimit","g":"ai","word":"Notzungslimit","text":"Wéi vill KI-Aarbecht däi Plang an enger Period erlaabt; duerno gëtt se ënnerbrach oder kascht méi.","also":["Notzungslimiten","Usage Limit","Usage Limits"]},{"id":"vibe","g":"ai","word":"Vibe Coding","text":"Software meeschtens bauen, andeems een enger KI beschreift, wat ee wëll, a se de Code schreiwe léisst.","also":["Vibe-Coding"]},{"id":"budget","g":"money","word":"Budget","text":"De Betrag u Geld, deen fir eppes op d'Säit geluecht ass.","also":["Budgeten","Budgets"],"noTip":1},{"id":"costest","g":"money","word":"Käschteschätzung","text":"Déi bescht Schätzung, wat eppes kascht, ier s du ufänks.","also":["Käschteschätzungen","Cost Estimate","Cost Estimates"]},{"id":"roi","g":"money","word":"Return on Investment (ROI)","text":"Wat s du erëmkriss, am Verglach mat deem, wat s du agesat hues. Ass et positiv, huet et sech gelount.","also":["ROI","Rendement"]},{"id":"tco","g":"money","word":"Total Cost of Ownership (TCO)","text":"Alles, wat eppes wierklech iwwer säi ganzt Liewe kascht, net nëmmen de Kafpräis: Bedrib, Support, Upgrades a schlussendlech d'Ofschafen.","also":["TCO","Gesamtkäschte"]},{"id":"capex","g":"money","word":"CapEx an OpEx","text":"CapEx ass Geld, dat am Viraus fir Saachen ausgi gëtt, déi s du behäls; OpEx sinn lafend Ausgaben, wéi Rechnungen all Mount.","also":["CapEx","OpEx","Capital Expenditure","Operating Expenditure"]},{"id":"subscription","g":"money","word":"Abonnement","text":"Regelméisseg bezuelen, meeschtens all Mount oder all Joer, fir eppes weider benotzen ze kënnen.","also":["Abonnementer","Subscription","Subscriptions","Abo"],"noTip":1},{"id":"saas","g":"money","word":"Software as a Service (SaaS)","text":"Software, déi s du online benotz an per Abonnement bezuels, wärend den Hiersteller se fir dech bedreift.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Nëmmen dat bezuelen, wat s du benotz, wéi bei Cloud Computing oder KI-Tokens.","also":["Pay-as-you-go","Usage-Based Pricing","Bezuele fir de Verbrauch"]},{"id":"overage","g":"money","word":"Iwwerverbrauch","text":"Notzung iwwer dat eraus, wat an dengem Plang abegraff ass, wat extra kaschte kann.","also":["Overage","Overages","Overage Charges"]},{"id":"billingalert","g":"money","word":"Rechnungsalarm","text":"E Message, wann d'Ausgaben oder d'Notzung en Niveau erreechen, deen s du gewielt hues. E warnt dech, stoppt awer net ëmmer weider Käschten.","also":["Rechnungsalarmer","Billing Alert","Billing Alerts","Spending Alert","Ausgabenalarm"]},{"id":"freetier","g":"money","word":"Gratis-Stuf","text":"Eng gratis Stuf vun engem bezuelte Service, mat Limiten. Praktesch fir unzefänken.","also":["Gratis-Plang","Free Tier","Free Plan"]},{"id":"pricing","g":"money","word":"Präisplang","text":"Déi verschidde Paketen, déi e Service verkeeft, all eent mat sengem eegene Präis a senge Limiten.","also":["Präispläng","Pricing Plan","Pricing Plans","Price Plan"]},{"id":"licence","g":"money","word":"Lizenz","text":"D'Reegelen, wéi s du eppes, wat een anere gemaach huet, benotzen, kopéieren, änneren oder deelen däerfs, wéi Software, Schrëften oder Biller.","also":["Lizenzen","Licence","Licences","License","Licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open Source","text":"Software, vun där jiddereen de Code liesen, benotzen an dacks gratis ännere kann, no de Reegele vun hirer Lizenz.","also":["Open-Source","Open-Source-Software","Open Source Software","OSS"]},{"id":"osslicence","g":"money","word":"Open-Source-Lizenz","text":"D'Reegelen, déi mat Open-Source-Code kommen. Verschidde loossen dech bal alles maachen (wéi MIT); verschidde verlaangen, datt s du deng Ännerungen och deels (wéi GPL).","also":["Open-Source-Lizenzen","Open Source Licence","Open Source Licences","MIT-Lizenz","MIT Licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietär","text":"Vun enger Firma besëtzt a net fräi zum Kopéieren oder Änneren. D'Géigendeel vun Open Source.","also":["Proprietär Software","Proprietary","Proprietary Software"]},{"id":"copyright","g":"money","word":"Copyright","text":"D'gesetzlecht Recht vun engem Schëpfer, d'Kopië vu senger Aarbecht ze kontrolléieren, och Code a Schrëftlechem.","also":["copyrighted","Urheberrecht"],"noTip":1},{"id":"ip","g":"money","word":"Intellektuellt Eegentum (IP)","text":"Iddien a Wierker, déi d'Gesetz als Eegentum behandelt, wéi Code, Designen, Nimm a Logoen.","also":["Intellectual Property","IP","geeschtegt Eegentum"]},{"id":"tos","g":"money","word":"Notzungskonditiounen","text":"D'Reegelen, déi s du akzeptéiers, wann s du e Service benotz.","also":["Terms of Service","Terms and Conditions","Terms of Use","Notzungsbedingungen","Konditiounen"]},{"id":"contract","g":"money","word":"Kontrakt","text":"E schrëftlechen Accord tëscht zwou Säiten, deen d'Gesetz ënnerstëtzt.","also":["Kontrakter","Contract","Contracts","Vertrag"],"noTip":1},{"id":"sow","g":"money","word":"Statement of Work (SOW)","text":"En Dokument, dat genee festhält, wéi eng Aarbecht bis wéini a fir wéi vill gemaach gëtt.","also":["SOW","Leeschtungsbeschreiwung"]},{"id":"fixedprice","g":"money","word":"Festpräis","text":"E festgeluechte Präis fir déi ganz Aarbecht, egal wéi laang se dauert.","also":["Fixed Price","Fixed-Price","Pauschalpräis"]},{"id":"tm","g":"money","word":"Time and Materials","text":"D'Stonnen, déi wierklech geschafft goufen, an d'Saachen, déi wierklech benotzt goufen, bezuelen, amplaz e festen Präis.","also":["T&M","Opwand a Material"]},{"id":"invoice","g":"money","word":"Rechnung","text":"En Dokument, mat deem eng Bezuelung fir gemaachten Aarbecht oder geliwwert Wuer ugefrot gëtt.","also":["Rechnungen","Invoice","Invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor Lock-in","text":"Wann et esou schwéier oder deier ass, vun engem Liwwerant ewechzegoen, datt s du bei him hänke bleiws.","also":["Lock-in","Ofhängegkeet vum Liwwerant"]},{"id":"procurement","g":"money","word":"Akaf (Procurement)","text":"De Prozess, fir Liwweranten erauszesichen a bei hinnen anzekafen.","also":["Procurement","Akaf"]},{"id":"servicecredit","g":"money","word":"Service-Credit","text":"Geld zréck oder e Rabatt, deen s du kriss, wann e Liwwerant säin SLA net anhält.","also":["Service-Credits","Service Credit","Service Credits"]}]}};
